PathwayData.put("data/reading_writing/units/L03U5.json",{"strand":"reading_writing","level":3,"cefr":"A2a","unit":5,"theme":"Stories from Long Ago","essential_question":"What can old stories teach us?","schema_version":"1.0","core_words":["king","palace","village","merchant","wise","clever","brave","lesson","treasure","honest","greedy","reward","shepherd","story"],"recycled_words":["problem","solution","lesson","kind","honest","generous","proud","because","so","long ago","character","camel","desert"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L03-U5-LS1","title":"Word Power: Stories from Long Ago","lesson_type":"vocabulary","objectives":["read, say and use 14 words from folktales and 3 Tier 2 words (theme, synonym, consequence)","use a synonym clue (a word with almost the same meaning nearby) to understand a new word","describe folktale characters with precise trait words (wise, clever, brave, honest, greedy)"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة من الحكايات الشعبية و3 كلمات أكاديمية (theme, synonym, consequence).","استخدام دليل المرادف (كلمة قريبة المعنى بالقرب منها) لفهم كلمة جديدة.","وصف شخصيات الحكايات بكلمات صفات دقيقة."],"success_criteria":["I can read and use the folktale words in sentences.","I can find a synonym clue and explain a new word.","I can match trait words to folktale characters."],"success_criteria_ar":["أستطيع قراءة كلمات الحكايات واستخدامها في جمل.","أستطيع إيجاد دليل المرادف وشرح كلمة جديدة.","أستطيع مطابقة كلمات الصفات مع شخصيات الحكايات."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"king","pos":"noun","ipa":"/kɪŋ/","definition":"a man who rules a country","arabic":"ملك","example":"The wise king listened carefully.","image_id":"IMG-RW-L03-U5-LS1-V01","audio_id":"AUD-RW-L03-U5-LS1-V01","tier":"core"},{"word":"palace","pos":"noun","ipa":"/ˈpæləs/","definition":"a very big, beautiful house where a king lives","arabic":"قصر","example":"The king lived in a white palace.","image_id":"IMG-RW-L03-U5-LS1-V02","audio_id":"AUD-RW-L03-U5-LS1-V02","tier":"core"},{"word":"village","pos":"noun","ipa":"/ˈvɪlɪdʒ/","definition":"a very small town in the countryside","arabic":"قرية","example":"The shepherd lived in a small village.","image_id":"IMG-RW-L03-U5-LS1-V03","audio_id":"AUD-RW-L03-U5-LS1-V03","tier":"core"},{"word":"merchant","pos":"noun","ipa":"/ˈmɝtʃənt/","definition":"a person who buys and sells things","arabic":"تاجر","example":"The merchant sold silk and spices.","image_id":"IMG-RW-L03-U5-LS1-V04","audio_id":"AUD-RW-L03-U5-LS1-V04","tier":"core"},{"word":"wise","pos":"adjective","ipa":"/waɪz/","definition":"having good judgment and knowledge","arabic":"حكيم","example":"The wise king solved the problem.","image_id":"IMG-RW-L03-U5-LS1-V05","audio_id":"AUD-RW-L03-U5-LS1-V05","tier":"core"},{"word":"clever","pos":"adjective","ipa":"/ˈklɛvər/","definition":"quick to understand and good at finding answers","arabic":"ذكي / فطن","example":"The clever shepherd answered every riddle.","image_id":"IMG-RW-L03-U5-LS1-V06","audio_id":"AUD-RW-L03-U5-LS1-V06","tier":"core"},{"word":"brave","pos":"adjective","ipa":"/breɪv/","definition":"not afraid to do something hard or dangerous","arabic":"شجاع","example":"The brave girl walked into the dark cave.","image_id":"IMG-RW-L03-U5-LS1-V07","audio_id":"AUD-RW-L03-U5-LS1-V07","tier":"core"},{"word":"lesson","pos":"noun","ipa":"/ˈlɛsən/","definition":"something you learn from what happens","arabic":"درس / عبرة","example":"The story teaches a lesson about honesty.","image_id":"IMG-RW-L03-U5-LS1-V08","audio_id":"AUD-RW-L03-U5-LS1-V08","tier":"core"},{"word":"treasure","pos":"noun","ipa":"/ˈtrɛʒər/","definition":"gold, jewels or something very valuable","arabic":"كنز","example":"They found a box of treasure.","image_id":"IMG-RW-L03-U5-LS1-V09","audio_id":"AUD-RW-L03-U5-LS1-V09","tier":"core"},{"word":"honest","pos":"adjective","ipa":"/ˈɑnɪst/","definition":"telling the truth and not taking what is not yours","arabic":"أمين / صادق","example":"The honest boy returned the bag.","image_id":"IMG-RW-L03-U5-LS1-V10","audio_id":"AUD-RW-L03-U5-LS1-V10","tier":"core"},{"word":"greedy","pos":"adjective","ipa":"/ˈɡridi/","definition":"wanting more and more than you need","arabic":"طمّاع / جشع","example":"The greedy merchant wanted all the gold.","image_id":"IMG-RW-L03-U5-LS1-V11","audio_id":"AUD-RW-L03-U5-LS1-V11","tier":"core"},{"word":"reward","pos":"noun / verb","ipa":"/rɪˈwɔrd/","definition":"something given for good work or help; to give this","arabic":"مكافأة / يكافئ","example":"The king gave him a reward.","image_id":"IMG-RW-L03-U5-LS1-V12","audio_id":"AUD-RW-L03-U5-LS1-V12","tier":"core"},{"word":"shepherd","pos":"noun","ipa":"/ˈʃɛpərd/","definition":"a person who looks after sheep","arabic":"راعٍ","example":"The shepherd took his sheep to the hills.","image_id":"IMG-RW-L03-U5-LS1-V13","audio_id":"AUD-RW-L03-U5-LS1-V13","tier":"core"},{"word":"story","pos":"noun","ipa":"/ˈstɔri/","definition":"words that tell about events, real or made up","arabic":"قصة / حكاية","example":"Grandma told us a story from long ago.","image_id":"IMG-RW-L03-U5-LS1-V14","audio_id":"AUD-RW-L03-U5-LS1-V14","tier":"core"},{"word":"theme","pos":"noun","ipa":"/θim/","definition":"the big lesson or message of a story","arabic":"المغزى / الفكرة العامة","example":"The theme of the story is: honesty is the best treasure.","image_id":"IMG-RW-L03-U5-LS1-V15","audio_id":"AUD-RW-L03-U5-LS1-V15","tier":"tier2"},{"word":"synonym","pos":"noun","ipa":"/ˈsɪnənɪm/","definition":"a word that means almost the same as another word (clever – smart)","arabic":"مرادف","example":"*Brave* is a synonym of *courageous*.","image_id":"IMG-RW-L03-U5-LS1-V16","audio_id":"AUD-RW-L03-U5-LS1-V16","tier":"tier2"},{"word":"consequence","pos":"noun","ipa":"/ˈkɑnsəkwɛns/","definition":"what happens because of something you do","arabic":"عاقبة / نتيجة","example":"Losing his gold was the consequence of his lie.","image_id":"IMG-RW-L03-U5-LS1-V17","audio_id":"AUD-RW-L03-U5-LS1-V17","tier":"tier2"}],"explanation":{"text":"Sometimes a writer uses a **synonym** – a word with **almost the same meaning** – near a new word. The synonym is a **clue**.\n\nLook for the synonym in the **same sentence** or the **next sentence**. Signal words: **or**, **also**, **like**, **and**, or a word that **repeats the idea**: *The merchant was **greedy**. He always **wanted more** gold.*\n\nSteps: (1) Find the new word. (2) Look before and after it for a word you **know** that has a similar meaning. (3) Put the known word in place of the new word. Does the sentence still make sense?","examples":["*The shepherd was **clever**. Everyone said he was very **smart**.* → clever ≈ smart.","*The king was **wise**, and his advice was always **sensible**.* → wise ≈ sensible.","*The **brave** boy was not **afraid** of the dark cave.* → brave = not afraid.","*The merchant was **greedy**; he **wanted more and more** gold.* → greedy ≈ wanting more and more.","*They found a **treasure**, a box of **riches** and gold.* → treasure ≈ riches.","*The boy was **honest**. He always **told the truth**.* → honest ≈ truthful.","*The king gave Hamid a **reward**, or a **prize**, for his help.* → reward ≈ prize.","*The **village** was a small **town** in the mountains.* → village ≈ small town.","Check: *The shepherd was **smart**.* – it makes sense, so clever ≈ smart."],"common_errors":["✗ Thinking a synonym must be exactly the same. → ✓ Synonyms mean **almost** the same (big – huge). (Close meaning, not always identical.)","✗ Choosing an opposite as the clue. → ✓ *Not afraid* explains *brave*; *afraid* alone is the opposite. (Read carefully: is it the same or the opposite?)","✗ The king were wise. → ✓ The king was wise. (One king → **was**.)","✗ He gave him a reward for help him. → ✓ He gave him a reward for helping him. (for + **-ing**.)","✗ The greedy merchant want more gold. → ✓ The greedy merchant wanted more gold. (Folktales are told in the **past** tense.)","✗ A sheperd → ✓ a shepherd (Spelling: s-h-e-p-h-e-r-d (sheep + herd).)","✗ The theme is Hamid. → ✓ The theme is: Honesty is the best treasure. (A theme is a **lesson**, not a name.)"],"arabic":"أحيانًا يستخدم الكاتب مرادفًا (كلمة قريبة المعنى) قرب الكلمة الجديدة، فيكون المرادف دليلًا.\n\nابحث عن المرادف في الجملة نفسها أو الجملة التالية، ومن إشاراته: or, also, like, and، أو كلمة تكرر الفكرة نفسها.\n\nالخطوات: جِد الكلمة الجديدة، ثم ابحث قبلها وبعدها عن كلمة تعرفها بمعنى قريب، ثم ضعها مكانها وتأكد أن الجملة مفهومة.\n\nالمرادف معناه قريب جدًا وليس دائمًا مطابقًا تمامًا (big – huge). وانتبه لكتابة shepherd = sheep + herd."},"video":{"script":[{"time":"00:00–00:20","narration":"Grandpa Saleh opens his old story box. 'Long, long ago…'","on_screen":"Stories from Long Ago","visual":"An old wooden box opens; golden light and tiny palaces fly out."},{"time":"00:20–01:00","narration":"A king in a palace, a merchant in the market, a shepherd in a village!","on_screen":"king · palace · merchant · village · shepherd · story","visual":"Paper-cut style scenes of each character and place."},{"time":"01:00–01:35","narration":"Wise, clever, brave, honest – or greedy? Characters learn a lesson, find treasure or get a reward.","on_screen":"wise · clever · brave · honest · greedy · lesson · treasure · reward","visual":"Character cards flip to show trait words."},{"time":"01:35–02:30","narration":"New word? Find its synonym! The shepherd was clever. Everyone said he was very smart. Clever ≈ smart!","on_screen":"Synonym clue = almost the same","visual":"Two word cards slide together with a ≈ sign."},{"time":"02:30–03:00","narration":"Every story has a theme – a big lesson. And every choice has a consequence!","on_screen":"theme · synonym · consequence","visual":"A domino chain ends at a lesson card."}],"captions_ar":["يفتح الجد صالح صندوق حكاياته القديم: «في قديم الزمان…»","ملك في قصر، وتاجر في السوق، وراعٍ في قرية!","حكيم، ذكي، شجاع، أمين… أم طمّاع؟ الشخصيات تتعلم درسًا أو تجد كنزًا أو تنال مكافأة.","كلمة جديدة؟ ابحث عن مرادفها! The shepherd was clever… he was very smart.","لكل حكاية مغزى، ولكل اختيار عاقبة!"],"voice":"Narrator: American English, warm storyteller voice (female), speed 0.90. Grandpa Saleh opens the story box with a deep, gentle voice."},"texts":[],"activities":[{"id":"RW-L03-U5-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"A man who rules a country is a ___.","answer":"king","explanation":"King = ruler.","explanation_ar":"ملك.","options":["merchant","king","shepherd","village"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The king lives in a big, beautiful ___.","answer":"palace","explanation":"Palace = king's house.","explanation_ar":"قصر.","options":["village","treasure","lesson","palace"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A person who buys and sells things is a ___.","answer":"merchant","explanation":"Merchant = trader.","explanation_ar":"تاجر.","options":["merchant","shepherd","king","palace"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A person who looks after sheep is a ___.","answer":"shepherd","explanation":"Shepherd = sheep.","explanation_ar":"راعٍ.","options":["merchant","king","treasure","shepherd"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Gold and jewels in a big box are ___.","answer":"treasure","explanation":"Treasure = valuable things.","explanation_ar":"كنز.","options":["a lesson","a village","treasure","a reward only"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A boy who tells the truth and returns what is not his is ___.","answer":"honest","explanation":"Honest = truthful.","explanation_ar":"أمين.","options":["greedy","honest","brave only","clever only"],"dok":1,"skill":"character traits","stage":"controlled"}]},{"id":"RW-L03-U5-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Find the synonym clue. Choose the meaning.","instructions_ar":"جِد دليل المرادف واختر المعنى.","items":[{"q":"*The shepherd was **clever**. Everyone said he was very smart.* *Clever* means ___.","answer":"smart","explanation":"Synonym clue: smart.","explanation_ar":"ذكي.","options":["lazy","old","smart","rich"],"dok":1,"skill":"synonym clues","stage":"guided"},{"q":"*The merchant was **greedy**; he always wanted more and more gold.* *Greedy* means ___.","answer":"wanting more and more","explanation":"Synonym phrase.","explanation_ar":"طمّاع.","options":["sharing everything","wanting more and more","very kind","very tired"],"dok":1,"skill":"synonym clues","stage":"guided"},{"q":"*The king gave Hamid a **reward**, or a prize, for his help.* Which word is the synonym clue?","answer":"prize","explanation":"or + prize.","explanation_ar":"prize.","options":["king","help","gave","prize"],"dok":2,"skill":"synonym clues","stage":"guided"},{"q":"*The boy was **courageous**. He was brave and not afraid of the storm.* *Courageous* means ___.","answer":"brave","explanation":"Synonym clue: brave.","explanation_ar":"شجاع.","options":["brave","scared","hungry","noisy"],"dok":2,"skill":"synonym clues","stage":"guided"},{"q":"*The old man was **wise**, and his advice was always sensible.* Which word means almost the same as *wise*?","answer":"sensible","explanation":"sensible ≈ wise.","explanation_ar":"sensible.","options":["sensible","old","advice","always"],"dok":2,"skill":"synonym clues","stage":"guided"},{"q":"*The palace was **enormous** – it was huge, with a hundred rooms!* *Enormous* means ___.","answer":"huge","explanation":"Synonym clue: huge.","explanation_ar":"ضخم.","options":["tiny","dark","huge","new"],"dok":2,"skill":"synonym clues","stage":"guided"}]},{"id":"RW-L03-U5-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"The ________ of the story is: Honesty is the best treasure.","answer":"theme","explanation":"The big lesson.","explanation_ar":"المغزى.","stage":"freer"},{"q":"*Big* and *large* are ________s.","answer":"synonym","explanation":"Words with almost the same meaning.","explanation_ar":"مترادفات.","stage":"freer"},{"q":"He lied, and the ________ was that he lost everything.","answer":"consequence","explanation":"What happens because of an action.","explanation_ar":"العاقبة.","stage":"freer"},{"q":"The ________ girl walked into the dark cave to save the lamb.","answer":"brave","explanation":"Not afraid.","explanation_ar":"الشجاعة.","stage":"freer"},{"q":"The shepherd lived in a small ________ near the mountains.","answer":"village","explanation":"A very small town.","explanation_ar":"قرية.","stage":"freer"},{"q":"Every folktale teaches a ________ we can use in our lives.","answer":"lesson","explanation":"Something you learn.","explanation_ar":"درسًا.","stage":"freer"}]},{"id":"RW-L03-U5-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Write a sentence with a synonym clue for *clever*.","answer":"The clever girl was smart enough to solve the riddle.","explanation":"clever + synonym.","explanation_ar":"clever + مرادف.","dok":2,"skill":"synonym clues","stage":"production"},{"q":"Write a synonym for each: *big, happy, brave*.","answer":"large, glad, fearless","explanation":"Three synonyms.","explanation_ar":"ثلاثة مرادفات.","dok":2,"skill":"synonyms","stage":"production"},{"q":"Describe a greedy character and an honest character from any story.","answer":"The greedy fox wanted all the grapes. The honest boy returned the lost bag.","explanation":"Two traits.","explanation_ar":"صفتان.","dok":2,"skill":"character traits","stage":"production"},{"q":"What is a lesson you learned from a story your family told you?","answer":"I learned that we should share, because sharing makes everyone happy.","explanation":"Lesson + because.","explanation_ar":"درس + because.","dok":3,"skill":"connect","stage":"production"}]}],"game":{"name":"Synonym Snap","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Synonym snap: two word cards flip at a time; the child taps 'Snap!' when they are synonyms. A correct snap opens a door in the palace.","Pairs share a deck, face down.","Players take turns turning over one card each.","If the two cards are synonyms, the first to say 'Snap!' and use both in a sentence keeps the cards.","If not, turn them back over.","The player with the most pairs wins."],"data":[]},"exit_quiz":[{"q":"A synonym is a word that ___.","answer":"means almost the same as another word","explanation":"Synonym = similar meaning.","explanation_ar":"معناه قريب جدًا.","options":["means the opposite","is a name","means almost the same as another word","has a prefix"],"dok":1,"skill":"synonyms"},{"q":"Which pair of size words are synonyms?","answer":"big – large","explanation":"Same meaning.","explanation_ar":"big – large.","options":["big – small","big – large","hot – cold","fast – slow"],"dok":1,"skill":"synonyms"},{"q":"Which word means *a very small town*?","answer":"village","explanation":"Village.","explanation_ar":"قرية.","options":["village","palace","treasure","merchant"],"dok":1,"skill":"vocabulary"},{"q":"*The theme of the story is about honesty.* *Theme* means ___.","answer":"the big lesson of a story","explanation":"Theme = lesson.","explanation_ar":"المغزى.","options":["the first page","the big lesson of a story","a character's name","a kind of treasure"],"dok":1,"skill":"vocabulary"},{"q":"Which character is GREEDY?","answer":"a merchant who wants all the gold for himself","explanation":"Greedy = wants more.","explanation_ar":"التاجر الطمّاع.","options":["a boy who shares his lunch","a king who helps the poor","a merchant who wants all the gold for himself","a shepherd who gives water to travelers"],"dok":2,"skill":"character traits"},{"q":"*The **foolish** man was not wise; he made silly choices.* *Foolish* means ___.","answer":"not wise; silly","explanation":"Clue: not wise, silly.","explanation_ar":"أحمق.","options":["not wise; silly","very brave","very rich","very honest"],"dok":2,"skill":"context clues"},{"q":"Which sentence about the king is correct?","answer":"The king was wise and kind.","explanation":"One king → was.","explanation_ar":"صحيحة.","options":["The king were wise and kind.","The king is wisely and kind.","The kings was wise.","The king was wise and kind."],"dok":2,"skill":"grammar"},{"q":"*He told a lie. The consequence was that nobody trusted him.* *Consequence* means ___.","answer":"what happens because of an action","explanation":"Consequence = result.","explanation_ar":"عاقبة.","options":["a type of story","a gold coin","what happens because of an action","a palace room"],"dok":2,"skill":"vocabulary in context"},{"q":"How does a synonym clue help you?","answer":"You can use a word you know to understand a new word.","explanation":"Known word → new word.","explanation_ar":"تفهم الكلمة الجديدة بكلمة تعرفها.","options":["It tells you the page number.","It makes the word longer.","It always gives the opposite.","You can use a word you know to understand a new word."],"dok":3,"skill":"strategy"},{"q":"Which word would you use to describe a character who returns lost money?","answer":"honest","explanation":"Returning money = honest.","explanation_ar":"أمين.","options":["greedy","honest","foolish","lazy"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L03-U5-LS1-V01","prompt":"Picture for the word 'king': a king on a throne with a crown"},{"id":"IMG-RW-L03-U5-LS1-V02","prompt":"Picture for the word 'palace': a palace with domes and gardens"},{"id":"IMG-RW-L03-U5-LS1-V03","prompt":"Picture for the word 'village': a mountain village with stone houses"},{"id":"IMG-RW-L03-U5-LS1-V04","prompt":"Picture for the word 'merchant': a merchant at a market stall"},{"id":"IMG-RW-L03-U5-LS1-V05","prompt":"Picture for the word 'wise': an old man thinking with a calm face"},{"id":"IMG-RW-L03-U5-LS1-V06","prompt":"Picture for the word 'clever': a boy with a light bulb above his head"},{"id":"IMG-RW-L03-U5-LS1-V07","prompt":"Picture for the word 'brave': a girl holding a lantern at a cave"},{"id":"IMG-RW-L03-U5-LS1-V08","prompt":"Picture for the word 'lesson': a light bulb over an open storybook"},{"id":"IMG-RW-L03-U5-LS1-V09","prompt":"Picture for the word 'treasure': an open chest full of gold"},{"id":"IMG-RW-L03-U5-LS1-V10","prompt":"Picture for the word 'honest': a boy handing back a purse"},{"id":"IMG-RW-L03-U5-LS1-V11","prompt":"Picture for the word 'greedy': a man hugging a pile of coins"},{"id":"IMG-RW-L03-U5-LS1-V12","prompt":"Picture for the word 'reward': a hand giving a small bag of coins"},{"id":"IMG-RW-L03-U5-LS1-V13","prompt":"Picture for the word 'shepherd': a shepherd with a stick and sheep"},{"id":"IMG-RW-L03-U5-LS1-V14","prompt":"Picture for the word 'story': a grandmother reading to children"},{"id":"IMG-RW-L03-U5-LS1-V15","prompt":"Picture for the word 'theme': an umbrella labelled 'theme' over a story"},{"id":"IMG-RW-L03-U5-LS1-V16","prompt":"Picture for the word 'synonym': two word cards joined by an equals sign"},{"id":"IMG-RW-L03-U5-LS1-V17","prompt":"Picture for the word 'consequence': a domino falling after a push"},{"id":"IMG-RW-L03-U5-LS1-01","prompt":"Grandpa opens a story box and folktale scenes rise from it."},{"id":"IMG-RW-L03-U5-LS1-02","prompt":"Synonym word cards joined by an almost-equal sign."},{"id":"IMG-RW-L03-U5-LS1-03","prompt":"Five folktale character cards."}],"audio":[{"id":"AUD-RW-L03-U5-LS1-V01","script":"king. The wise king listened carefully."},{"id":"AUD-RW-L03-U5-LS1-V02","script":"palace. The king lived in a white palace."},{"id":"AUD-RW-L03-U5-LS1-V03","script":"village. The shepherd lived in a small village."},{"id":"AUD-RW-L03-U5-LS1-V04","script":"merchant. The merchant sold silk and spices."},{"id":"AUD-RW-L03-U5-LS1-V05","script":"wise. The wise king solved the problem."},{"id":"AUD-RW-L03-U5-LS1-V06","script":"clever. The clever shepherd answered every riddle."},{"id":"AUD-RW-L03-U5-LS1-V07","script":"brave. The brave girl walked into the dark cave."},{"id":"AUD-RW-L03-U5-LS1-V08","script":"lesson. The story teaches a lesson about honesty."},{"id":"AUD-RW-L03-U5-LS1-V09","script":"treasure. They found a box of treasure."},{"id":"AUD-RW-L03-U5-LS1-V10","script":"honest. The honest boy returned the bag."},{"id":"AUD-RW-L03-U5-LS1-V11","script":"greedy. The greedy merchant wanted all the gold."},{"id":"AUD-RW-L03-U5-LS1-V12","script":"reward. The king gave him a reward."},{"id":"AUD-RW-L03-U5-LS1-V13","script":"shepherd. The shepherd took his sheep to the hills."},{"id":"AUD-RW-L03-U5-LS1-V14","script":"story. Grandma told us a story from long ago."},{"id":"AUD-RW-L03-U5-LS1-V15","script":"theme. The theme of the story is: honesty is the best treasure."},{"id":"AUD-RW-L03-U5-LS1-V16","script":"synonym. *Brave* is a synonym of *courageous*."},{"id":"AUD-RW-L03-U5-LS1-V17","script":"consequence. Losing his gold was the consequence of his lie."},{"id":"AUD-RW-L03-U5-LS1-VID","script":"Grandpa Saleh opens his old story box. 'Long, long ago…' A king in a palace, a merchant in the market, a shepherd in a village! Wise, clever, brave, honest – or greedy? Characters learn a lesson, find treasure or get a reward. New word? Find its synonym! The shepherd was clever. Everyone said he was very smart. Clever ≈ smart! Every story has a theme – a big lesson. And every choice has a consequence!"}]},{"id":"RW-L03-U5-LS2","title":"The Merchant and the Honest Boy","lesson_type":"close_reading","objectives":["read a folktale of about 240 words and recount it in order","identify the features of a folktale (long ago, good and bad characters, a test, a wise solution, a lesson)","explain how the characters' choices lead to consequences"],"objectives_ar":["قراءة حكاية شعبية من نحو 240 كلمة وإعادة سردها بالترتيب.","تحديد خصائص الحكاية الشعبية.","شرح كيف تؤدي اختيارات الشخصيات إلى عواقب."],"success_criteria":["I can recount the folktale in order.","I can find three features that make it a folktale.","I can explain the consequence of each main character's choice."],"success_criteria_ar":["أستطيع إعادة سرد الحكاية بالترتيب.","أستطيع إيجاد ثلاث خصائص تجعلها حكاية شعبية.","أستطيع شرح عاقبة اختيار كل شخصية رئيسية."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"leather","pos":"noun","ipa":"/ˈlɛðər/","definition":"material made from animal skin","arabic":"جلد (مادة)","example":"Jaber had a leather bag.","image_id":"IMG-RW-L03-U5-LS2-V01","audio_id":"AUD-RW-L03-U5-LS2-V01","tier":"core"},{"word":"coin","pos":"noun","ipa":"/kɔɪn/","definition":"a round piece of metal money","arabic":"عملة معدنية","example":"The bag was full of gold coins.","image_id":"IMG-RW-L03-U5-LS2-V02","audio_id":"AUD-RW-L03-U5-LS2-V02","tier":"core"},{"word":"well","pos":"noun","ipa":"/wɛl/","definition":"a deep hole in the ground for getting water","arabic":"بئر","example":"Hamid found the bag near the well.","image_id":"IMG-RW-L03-U5-LS2-V03","audio_id":"AUD-RW-L03-U5-LS2-V03","tier":"core"},{"word":"lie","pos":"verb / noun","ipa":"/laɪ/","definition":"to say something that is not true (past: lied)","arabic":"يكذب / كذبة","example":"The merchant lied about the coins.","image_id":"IMG-RW-L03-U5-LS2-V04","audio_id":"AUD-RW-L03-U5-LS2-V04","tier":"core"},{"word":"owner","pos":"noun","ipa":"/ˈoʊnər/","definition":"the person something belongs to","arabic":"المالك","example":"Who is the owner of this bag?","image_id":"IMG-RW-L03-U5-LS2-V05","audio_id":"AUD-RW-L03-U5-LS2-V05","tier":"core"},{"word":"count","pos":"verb","ipa":"/kaʊnt/","definition":"to find the number of things","arabic":"يعدّ","example":"Jaber counted the coins.","image_id":"IMG-RW-L03-U5-LS2-V06","audio_id":"AUD-RW-L03-U5-LS2-V06","tier":"core"},{"word":"folktale","pos":"noun","ipa":"/ˈfoʊkteɪl/","definition":"an old story told by people for many years, often with a lesson","arabic":"حكاية شعبية","example":"Grandpa told us a folktale.","image_id":"IMG-RW-L03-U5-LS2-V07","audio_id":"AUD-RW-L03-U5-LS2-V07","tier":"core"}],"explanation":{"text":"A **folktale** is an old story that people told **aloud** for many years before it was written down. Folktales from many countries have the **same features**.\n\nFeatures: (1) a **long-ago setting** (*Long ago, in a busy village…*); (2) **simple good and bad characters** (honest Hamid, greedy Jaber); (3) a **problem or test**; (4) a **wise or clever solution** (the king's idea); (5) a **lesson** at the end.\n\nIn folktales, **choices have consequences**: good choices are **rewarded** and bad choices are **punished**. Ask: **What did the character choose? What happened because of it?**","examples":["Long-ago setting: **Long ago, in a busy village by the river…**","Good character: **Hamid** – honest; he returns the bag even though his family needs money.","Bad character: **Jaber** – greedy; he lies to avoid paying the reward.","Wise character: **the king** – he listens carefully and finds a clever answer.","Problem / test: **Will Hamid keep the gold? Will Jaber pay the reward?**","Clever solution: **100 coins were lost, but this bag has 90 – so it cannot be Jaber's bag!**","Consequence for Jaber: **He lost all his gold.**","Consequence for Hamid: **He got a reward much bigger than ten coins.**","Lesson: **\"Honesty is the best treasure.\"**"],"common_errors":["✗ The king is greedy. → ✓ The king is wise; Jaber is greedy. (Match each trait to the right character.)","✗ Jaber lose his gold. → ✓ Jaber lost his gold. (Folktales use the **past tense**: lost.)","✗ Hamid finded the bag. → ✓ Hamid found the bag. (Irregular past: find → **found**.)","✗ The merchant lie to the king. → ✓ The merchant lied to the king. (Past: lie → **lied**.)","✗ The lesson is: the bag had 90 coins. → ✓ The lesson is: Honesty is the best treasure. (A lesson is a big idea, not a detail.)","✗ Jaber gave the reward. → ✓ Jaber did not want to pay the reward. (Check the text carefully.)"],"arabic":"الحكاية الشعبية قصة قديمة رواها الناس شفهيًا سنوات طويلة قبل أن تُكتب، ولحكايات الشعوب خصائص مشتركة.\n\nخصائصها: زمن قديم (Long ago)، وشخصيات بسيطة طيبة وشريرة، ومشكلة أو اختبار، وحل حكيم أو ذكي، ودرس في النهاية.\n\nفي الحكايات الشعبية للاختيارات عواقب: الاختيار الجيد يُكافأ والسيئ يُعاقب.\n\nفي الحكاية: حامد الأمين أعاد الكيس، وجابر الطماع كذب، والملك الحكيم وجد الحل الذكي."},"video":{"script":[{"time":"00:00–00:20","narration":"Long, long ago… Grandpa Saleh tells a folktale about a bag of gold!","on_screen":"A Folktale 📜","visual":"Paper-cut style: a river village, a busy market."},{"time":"00:20–01:45","narration":"Long ago, in a busy village by the river, there lived a rich merchant named Jaber…","on_screen":"(story, part by part)","visual":"Shadow-puppet animation: the lost bag, Hamid at the well, Jaber's lie, the king's palace, the clever answer."},{"time":"01:45–02:20","narration":"What makes it a folktale? Long ago… good and bad characters… a test… a wise answer… a lesson!","on_screen":"5 folktale features","visual":"Five stars light up one by one with labels."},{"time":"02:20–02:45","narration":"Choices and consequences: Hamid was honest – reward! Jaber was greedy – he lost everything!","on_screen":"Choice → consequence","visual":"A balance tips: Hamid up with a gift, Jaber down with an empty bag."},{"time":"02:45–03:00","narration":"Honesty is the best treasure!","on_screen":"The lesson 💎","visual":"A treasure chest opens to show the word HONESTY."}],"captions_ar":["في قديم الزمان… يحكي الجد صالح حكاية شعبية عن كيس من الذهب!","في قديم الزمان، في قرية مزدحمة على ضفة النهر، عاش تاجر غني اسمه جابر…","ما الذي يجعلها حكاية شعبية؟ زمن قديم، شخصيات طيبة وشريرة، اختبار، حل حكيم، ودرس!","الاختيارات والعواقب: حامد كان أمينًا فكوفئ، وجابر كان طمّاعًا فخسر كل شيء!","الأمانة أعظم كنز!"],"voice":"Narrator: American English, warm storyteller (female), speed 0.90. Jaber: loud, sly merchant. Hamid: quiet, honest boy. King: calm and wise."},"texts":[{"type":"reading","title":"The Merchant and the Honest Boy","body":"Long ago, in a busy village by the river, there lived a rich merchant named Jaber. One day, he lost a leather bag full of gold coins in the market. \"I will give a reward of ten coins to anyone who finds my bag!\" he shouted.\n\nA poor shepherd boy named Hamid found the bag near the well. He opened it and saw the shining gold. Hamid's family needed money, but he thought, \"This gold is not mine.\" He walked to Jaber's shop and gave him the bag.\n\nJaber counted the coins. He was happy, but he was also greedy. He did not want to pay the reward. \"There were one hundred coins in my bag,\" he lied. \"Now there are only ninety. You took ten coins, boy!\"\n\nHamid and the merchant went to the wise king at the palace. The king listened carefully. Then he smiled. \"Merchant, you say your bag had one hundred coins. This bag has only ninety. So this cannot be your bag! Hamid, keep this bag until its real owner comes.\"\n\nThe greedy merchant lost all his gold, and the honest boy got a reward much bigger than ten coins. From that day on, everyone in the village said, \"Honesty is the best treasure.\"","word_count":209,"audio_id":"AUD-RW-L03-U5-LS2-T1","id":"TXT-RW-L03-U5-LS2-1","genre":"narrative","role":"main","difficulty":"350L–500L","glossary":[{"word":"leather","definition":"material made from animal skin","arabic":"جلد"},{"word":"lied","definition":"said something that is not true (past of lie)","arabic":"كذب"},{"word":"owner","definition":"the person something belongs to","arabic":"المالك / صاحب الشيء"}]}],"activities":[{"id":"RW-L03-U5-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the folktale. Choose the answer.","instructions_ar":"اقرأ الحكاية واختر الإجابة.","items":[{"q":"Where did the story happen?","answer":"in a busy village by the river","explanation":"Paragraph 1.","explanation_ar":"في قرية على النهر.","options":["in a big city with cars","on a ship","in a forest","in a busy village by the river"],"dok":1,"skill":"setting","stage":"controlled"},{"q":"What did Jaber lose?","answer":"a leather bag full of gold coins","explanation":"Paragraph 1.","explanation_ar":"كيسًا جلديًا مليئًا بالذهب.","options":["his shop","his sheep","a leather bag full of gold coins","a letter"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What reward did Jaber promise?","answer":"ten coins","explanation":"Paragraph 1.","explanation_ar":"عشر قطع نقدية.","options":["ten coins","one hundred coins","a palace","a sheep"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where did Hamid find the bag?","answer":"near the well","explanation":"Paragraph 2.","explanation_ar":"قرب البئر.","options":["in the palace","in Jaber's shop","on the river","near the well"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"How many coins were really in the bag?","answer":"ninety","explanation":"Paragraph 3.","explanation_ar":"تسعون.","options":["one hundred","ninety","ten","two hundred"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who solved the problem?","answer":"the wise king","explanation":"Paragraph 4.","explanation_ar":"الملك الحكيم.","options":["the wise king","Hamid's father","another merchant","the shepherd's sheep"],"dok":1,"skill":"characters","stage":"controlled"}]},{"id":"RW-L03-U5-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Folktale features, choices and consequences. Choose.","instructions_ar":"خصائص الحكاية والاختيارات والعواقب: اختر.","items":[{"q":"Which words show the long-ago setting of a folktale?","answer":"Long ago, in a busy village…","explanation":"Folktales start long ago.","explanation_ar":"Long ago.","options":["From that day on…","The king listened carefully.","Long ago, in a busy village…","You took ten coins, boy!"],"dok":1,"skill":"folktale features","stage":"guided"},{"q":"Why did Hamid return the bag, even though his family needed money?","answer":"He knew the gold was not his.","explanation":"\"This gold is not mine.\"","explanation_ar":"لأن الذهب ليس له.","options":["He knew the gold was not his.","He wanted the king's palace.","The bag was too heavy.","Jaber saw him."],"dok":2,"skill":"motivation","stage":"guided"},{"q":"Why did Jaber lie about the coins?","answer":"He did not want to pay the reward.","explanation":"Paragraph 3.","explanation_ar":"لم يرد دفع المكافأة.","options":["He could not count.","He wanted to help Hamid.","The king told him to.","He did not want to pay the reward."],"dok":2,"skill":"motivation","stage":"guided"},{"q":"Why was the king's answer clever?","answer":"Jaber said his bag had 100 coins, so a bag with 90 could not be his.","explanation":"He used Jaber's own lie.","explanation_ar":"استخدم كذبة جابر نفسها.","options":["The king counted to one thousand.","Jaber said his bag had 100 coins, so a bag with 90 could not be his.","The king was very rich.","The king took the gold himself."],"dok":3,"skill":"reasoning","stage":"guided"},{"q":"What was the consequence of Jaber's lie?","answer":"He lost all his gold.","explanation":"Paragraph 5.","explanation_ar":"خسر كل ذهبه.","options":["He got a bigger reward.","He lost all his gold.","He became king.","Nothing happened."],"dok":2,"skill":"consequences","stage":"guided"},{"q":"What was the consequence of Hamid's honesty?","answer":"He got a reward much bigger than ten coins.","explanation":"Paragraph 5.","explanation_ar":"نال مكافأة أكبر.","options":["He went to prison.","He lost his sheep.","He got a reward much bigger than ten coins.","He had to pay Jaber."],"dok":2,"skill":"consequences","stage":"guided"}]},{"id":"RW-L03-U5-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that shows Hamid is honest.","answer":"Hamid's family needed money, but he thought, \"This gold is not mine.\"","explanation":"His thought shows honesty.","explanation_ar":"تفكيره يُظهر أمانته.","evidence":"Hamid's family needed money, but he thought, \"This gold is not mine.\"","text_id":"TXT-RW-L03-U5-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Long ago, in a busy village by the river, there lived a rich merchant named Jaber.","One day, he lost a leather bag full of gold coins in the market.","\"I will give a reward of ten coins to anyone who finds my bag!\" he shouted.","A poor shepherd boy named Hamid found the bag near the well.","He opened it and saw the shining gold.","Hamid's family needed money, but he thought, \"This gold is not mine.\"","He walked to Jaber's shop and gave him the bag.","Jaber counted the coins.","He was happy, but he was also greedy.","He did not want to pay the reward.","\"There were one hundred coins in my bag,\" he lied.","\"Now there are only ninety.","You took ten coins, boy!\"","Hamid and the merchant went to the wise king at the palace.","The king listened carefully.","Then he smiled.","\"Merchant, you say your bag had one hundred coins.","This bag has only ninety.","So this cannot be your bag!","Hamid, keep this bag until its real owner comes.\"","The greedy merchant lost all his gold, and the honest boy got a reward much bigger than ten coins.","From that day on, everyone in the village said, \"Honesty is the best treasure.\""]},{"q":"Underline Jaber's lie.","answer":"\"There were one hundred coins in my bag,\" he lied.","explanation":"The word 'lied' shows it.","explanation_ar":"كلمة lied تُظهرها.","evidence":"\"There were one hundred coins in my bag,\" he lied.","text_id":"TXT-RW-L03-U5-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Long ago, in a busy village by the river, there lived a rich merchant named Jaber.","One day, he lost a leather bag full of gold coins in the market.","\"I will give a reward of ten coins to anyone who finds my bag!\" he shouted.","A poor shepherd boy named Hamid found the bag near the well.","He opened it and saw the shining gold.","Hamid's family needed money, but he thought, \"This gold is not mine.\"","He walked to Jaber's shop and gave him the bag.","Jaber counted the coins.","He was happy, but he was also greedy.","He did not want to pay the reward.","\"There were one hundred coins in my bag,\" he lied.","\"Now there are only ninety.","You took ten coins, boy!\"","Hamid and the merchant went to the wise king at the palace.","The king listened carefully.","Then he smiled.","\"Merchant, you say your bag had one hundred coins.","This bag has only ninety.","So this cannot be your bag!","Hamid, keep this bag until its real owner comes.\"","The greedy merchant lost all his gold, and the honest boy got a reward much bigger than ten coins.","From that day on, everyone in the village said, \"Honesty is the best treasure.\""]},{"q":"Which word BEST describes the king?","answer":"wise","explanation":"He listened and found a clever answer.","explanation_ar":"حكيم.","options":["wise","greedy","lazy","dishonest"],"dok":2,"skill":"character traits","stage":"freer"},{"q":"What is the lesson of the folktale?","answer":"Honesty is the best treasure.","explanation":"Last sentence.","explanation_ar":"الأمانة أعظم كنز.","options":["Gold is easy to find.","Kings are rich.","Never go to the market.","Honesty is the best treasure."],"dok":2,"skill":"lesson","stage":"freer"}]},{"id":"RW-L03-U5-LS2-A4","type":"open","stage":"production","instructions":"Writing: Explain and evaluate.","instructions_ar":"اشرح وقيّم.","items":[{"q":"Recount the folktale in four sentences.","answer":"Jaber lost a bag of gold and promised a reward. Hamid found it and returned it. Jaber lied so he would not pay. The wise king gave the bag to Hamid.","explanation":"Four events in order.","explanation_ar":"أربعة أحداث مرتبة.","dok":2,"skill":"recount","stage":"production"},{"q":"Write Jaber's choice and its consequence with *so*.","answer":"Jaber lied about the coins, so he lost all his gold.","explanation":"Choice, so consequence.","explanation_ar":"اختيار، so عاقبة.","dok":2,"skill":"consequences","stage":"production"},{"q":"Was Hamid's choice easy? Why or why not?","answer":"No, because his family needed money, but he still returned the bag.","explanation":"Evaluate + reason.","explanation_ar":"تقييم + سبب.","dok":3,"skill":"evaluate","stage":"production"},{"q":"What would you say to Jaber if you were Hamid's friend?","answer":"You should tell the truth. Lying made you lose everything.","explanation":"Advice.","explanation_ar":"نصيحة.","dok":3,"skill":"apply","stage":"production"}]},{"id":"RW-L03-U5-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Merchant and the Honest Boy\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Merchant and the Honest Boy”.","answer":"209 words","title":"The Merchant and the Honest Boy","body":"Long ago, in a busy village by the river, there lived a rich merchant named Jaber. One day, he lost a leather bag full of gold coins in the market. \"I will give a reward of ten coins to anyone who finds my bag!\" he shouted.\n\nA poor shepherd boy named Hamid found the bag near the well. He opened it and saw the shining gold. Hamid's family needed money, but he thought, \"This gold is not mine.\" He walked to Jaber's shop and gave him the bag.\n\nJaber counted the coins. He was happy, but he was also greedy. He did not want to pay the reward. \"There were one hundred coins in my bag,\" he lied. \"Now there are only ninety. You took ten coins, boy!\"\n\nHamid and the merchant went to the wise king at the palace. The king listened carefully. Then he smiled. \"Merchant, you say your bag had one hundred coins. This bag has only ninety. So this cannot be your bag! Hamid, keep this bag until its real owner comes.\"\n\nThe greedy merchant lost all his gold, and the honest boy got a reward much bigger than ten coins. From that day on, everyone in the village said, \"Honesty is the best treasure.\"","words":209,"limit":194}],"time_limit_sec":194}],"game":{"name":"The King's Court","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Royal court: the child is the king's helper; a character steps forward, and the child chooses their choice, consequence and trait. Correct judgments fill the palace with light.","One student wears the crown as the 'judge'.","Teams get character, choice and consequence cards.","Teams match each character with their choice and consequence and say a trait.","The judge checks with the story evidence.","Correct set = 3 points."],"data":[]},"exit_quiz":[{"q":"Who is the main character who finds the bag?","answer":"Hamid","explanation":"Hamid found the bag.","explanation_ar":"حامد.","options":["Jaber","the king","Hamid's father","Hamid"],"dok":1,"skill":"characters"},{"q":"A folktale usually begins ___.","answer":"long ago","explanation":"Long-ago setting.","explanation_ar":"في زمن قديم.","options":["next week","in the future","long ago","today at school"],"dok":1,"skill":"folktale features"},{"q":"*He found the bag near the well.* A *well* is ___.","answer":"a deep hole for getting water","explanation":"Well = water hole.","explanation_ar":"بئر.","options":["a big shop","a kind of coin","a deep hole for getting water","a palace room"],"dok":1,"skill":"vocabulary"},{"q":"*Keep the bag until its real owner comes.* *Owner* means ___.","answer":"the person it belongs to","explanation":"Owner = belongs to.","explanation_ar":"المالك.","options":["the person who finds it","the king","the bag maker","the person it belongs to"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about Hamid uses the past tense correctly?","answer":"Hamid found the bag and returned it.","explanation":"find → found.","explanation_ar":"found.","options":["Hamid finded the bag and returned it.","Hamid found the bag and returned it.","Hamid find the bag and return it.","Hamid founded the bag."],"dok":2,"skill":"grammar"},{"q":"What made Jaber's lie fail?","answer":"He said 100 coins, but the bag had 90.","explanation":"The king used the numbers.","explanation_ar":"الأرقام كشفت كذبته.","options":["He said 100 coins, but the bag had 90.","Hamid told the king a secret.","The bag was empty.","The king saw Jaber take the coins."],"dok":2,"skill":"reasoning"},{"q":"Which pair of traits fits Hamid and Jaber?","answer":"honest – greedy","explanation":"Hamid honest; Jaber greedy.","explanation_ar":"أمين – طمّاع.","options":["honest – greedy","greedy – honest","brave – wise","lazy – clever"],"dok":2,"skill":"character traits"},{"q":"Why do folktales often have a wise king or judge?","answer":"to solve the problem fairly and show the lesson","explanation":"A wise solution is a feature.","explanation_ar":"لحل المشكلة بعدل وإظهار الدرس.","options":["to make the story longer","to solve the problem fairly and show the lesson","to sell the treasure","to scare the reader"],"dok":3,"skill":"genre"},{"q":"Which modern example matches the lesson of this folktale?","answer":"A girl finds a phone at school and gives it to the teacher.","explanation":"Honesty.","explanation_ar":"إعادة الهاتف المفقود.","options":["A boy wins a race.","A girl finds a phone at school and gives it to the teacher.","A family goes on a trip.","A cat climbs a tree."],"dok":3,"skill":"apply theme"},{"q":"Why does the story say *a reward much bigger than ten coins*?","answer":"Hamid kept the whole bag, which was more than the promised reward.","explanation":"He kept the bag of 90 coins.","explanation_ar":"احتفظ بالكيس كله.","options":["Hamid got a new sheep.","The king gave him a palace.","Hamid kept the whole bag, which was more than the promised reward.","Jaber paid twenty coins."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L03-U5-LS2-V01","prompt":"Picture for the word 'leather': a brown leather bag with a string"},{"id":"IMG-RW-L03-U5-LS2-V02","prompt":"Picture for the word 'coin': a pile of gold coins"},{"id":"IMG-RW-L03-U5-LS2-V03","prompt":"Picture for the word 'well': an old stone well with a bucket"},{"id":"IMG-RW-L03-U5-LS2-V04","prompt":"Picture for the word 'lie': a man with crossed fingers behind his back"},{"id":"IMG-RW-L03-U5-LS2-V05","prompt":"Picture for the word 'owner': a person holding a bag with a name tag"},{"id":"IMG-RW-L03-U5-LS2-V06","prompt":"Picture for the word 'count': hands counting coins in piles of ten"},{"id":"IMG-RW-L03-U5-LS2-V07","prompt":"Picture for the word 'folktale': a grandfather telling a story by a fire"},{"id":"IMG-RW-L03-U5-LS2-01","prompt":"Hamid holds a bag of gold coins by the well."},{"id":"IMG-RW-L03-U5-LS2-02","prompt":"Jaber accuses Hamid in front of the wise king."},{"id":"IMG-RW-L03-U5-LS2-03","prompt":"Five stars showing folktale features."}],"audio":[{"id":"AUD-RW-L03-U5-LS2-V01","script":"leather. Jaber had a leather bag."},{"id":"AUD-RW-L03-U5-LS2-V02","script":"coin. The bag was full of gold coins."},{"id":"AUD-RW-L03-U5-LS2-V03","script":"well. Hamid found the bag near the well."},{"id":"AUD-RW-L03-U5-LS2-V04","script":"lie. The merchant lied about the coins."},{"id":"AUD-RW-L03-U5-LS2-V05","script":"owner. Who is the owner of this bag?"},{"id":"AUD-RW-L03-U5-LS2-V06","script":"count. Jaber counted the coins."},{"id":"AUD-RW-L03-U5-LS2-V07","script":"folktale. Grandpa told us a folktale."},{"id":"AUD-RW-L03-U5-LS2-T1","script":"Long ago, in a busy village by the river, there lived a rich merchant named Jaber. One day, he lost a leather bag full of gold coins in the market. \"I will give a reward of ten coins to anyone who finds my bag!\" he shouted. A poor shepherd boy named Hamid found the bag near the well. He opened it and saw the shining gold. Hamid's family needed money, but he thought, \"This gold is not mine.\" He walked to Jaber's shop and gave him the bag. Jaber counted the coins. He was happy, but he was also greedy. He did not want to pay the reward. \"There were one hundred coins in my bag,\" he lied. \"Now there are only ninety. You took ten coins, boy!\" Hamid and the merchant went to the wise king at the palace. The king listened carefully. Then he smiled. \"Merchant, you say your bag had one hundred coins. This bag has only ninety. So this cannot be your bag! Hamid, keep this bag until its real owner comes.\" The greedy merchant lost all his gold, and the honest boy got a reward much bigger than ten coins. From that day on, everyone in the village said, \"Honesty is the best treasure.\""},{"id":"AUD-RW-L03-U5-LS2-VID","script":"Long, long ago… Grandpa Saleh tells a folktale about a bag of gold! Long ago, in a busy village by the river, there lived a rich merchant named Jaber… What makes it a folktale? Long ago… good and bad characters… a test… a wise answer… a lesson! Choices and consequences: Hamid was honest – reward! Jaber was greedy – he lost everything! Honesty is the best treasure!"}]},{"id":"RW-L03-U5-LS3","title":"Theme: the lesson of a story: \"The Clever Shepherd\"","lesson_type":"strategy_paired_text","objectives":["find the theme (big lesson) of a story and a play using the Theme Ladder","tell the difference between a lesson for one character and a theme for everyone","support a theme with evidence from what characters say and do"],"objectives_ar":["إيجاد مغزى القصة والمسرحية باستخدام سلّم المغزى.","التمييز بين درس لشخصية واحدة ومغزى للجميع.","دعم المغزى بالأدلة مما تقوله الشخصيات وتفعله."],"success_criteria":["I can climb the Theme Ladder: events → change → lesson → theme.","I can write a theme as a sentence for everyone.","I can give two pieces of evidence for a theme."],"success_criteria_ar":["أستطيع صعود سلّم المغزى: الأحداث ← التغيّر ← الدرس ← المغزى.","أستطيع كتابة المغزى كجملة تصلح للجميع.","أستطيع تقديم دليلين على المغزى."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"riddle","pos":"noun","ipa":"/ˈrɪdəl/","definition":"a tricky question with a clever answer","arabic":"لغز / أحجية","example":"The king asked three riddles.","image_id":"IMG-RW-L03-U5-LS3-V01","audio_id":"AUD-RW-L03-U5-LS3-V01","tier":"core"},{"word":"Your Majesty","pos":"phrase","ipa":"/jʊr ˈmædʒəsti/","definition":"a polite way to speak to a king or queen","arabic":"جلالتك","example":"Yes, Your Majesty.","image_id":"IMG-RW-L03-U5-LS3-V02","audio_id":"AUD-RW-L03-U5-LS3-V02","tier":"core"},{"word":"measure","pos":"verb","ipa":"/ˈmɛʒər/","definition":"to find out how big or long something is","arabic":"يقيس","example":"Measure the table with a ruler.","image_id":"IMG-RW-L03-U5-LS3-V03","audio_id":"AUD-RW-L03-U5-LS3-V03","tier":"core"},{"word":"believe","pos":"verb","ipa":"/bɪˈliv/","definition":"to think that something is true","arabic":"يصدّق","example":"If you do not believe me, measure it.","image_id":"IMG-RW-L03-U5-LS3-V04","audio_id":"AUD-RW-L03-U5-LS3-V04","tier":"core"},{"word":"invite","pos":"verb","ipa":"/ɪnˈvaɪt/","definition":"to ask someone to come","arabic":"يدعو","example":"The king invited the shepherd to the palace.","image_id":"IMG-RW-L03-U5-LS3-V05","audio_id":"AUD-RW-L03-U5-LS3-V05","tier":"core"},{"word":"surprised","pos":"adjective","ipa":"/sərˈpraɪzd/","definition":"feeling something unexpected happened","arabic":"متفاجئ","example":"The king was surprised by the answer.","image_id":"IMG-RW-L03-U5-LS3-V06","audio_id":"AUD-RW-L03-U5-LS3-V06","tier":"core"},{"word":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","definition":"an idea the writer wants readers to learn","arabic":"رسالة / فكرة يريد الكاتب إيصالها","example":"The message of the play is to help others.","image_id":"IMG-RW-L03-U5-LS3-V07","audio_id":"AUD-RW-L03-U5-LS3-V07","tier":"core"}],"explanation":{"text":"The **theme** is the **big lesson** or **message** of a story. It is true for **everyone**, not just for one character. Write it as a **full sentence**: *Honesty is the best treasure.*\n\nClimb the **Theme Ladder**: (1) **Events** – What happened? (2) **Character change** – How did a character change or what did they show? (3) **Lesson** – What did the character learn or teach? (4) **Theme** – What should **all** of us learn?\n\nA theme is **not** one word (*honesty*) and **not** a detail (*the bag had 90 coins*). Support it with **evidence**: what characters **say** and **do**, and how the story **ends**.","examples":["Story events: **Hamid returns the gold; Jaber lies; the king solves the problem.**","Character change: **Jaber goes from rich to having nothing because of his lie.**","Lesson for Hamid: **Doing the right thing brings good things.**","Theme for everyone: **Honesty is the best treasure.**","Play events: **The king tests Salim; Salim answers cleverly; Salim asks for a well for his village.**","What Salim shows: **He uses his cleverness to help others, not himself.**","Theme for everyone: **The best use of a clever mind is to help other people.**","Evidence: **SALIM: A new well for my village, so every family has water.**","Evidence: **KING: You are clever AND kind.**"],"common_errors":["✗ Theme: honesty. → ✓ Theme: Honesty is the best treasure. (Write the theme as a **sentence**.)","✗ Theme: Salim gets a well. → ✓ Theme: The best use of a clever mind is to help others. (A theme is a **lesson**, not an event.)","✗ Theme: Salim should be clever. → ✓ Theme: We should use our talents to help others. (Make it true for **everyone** (we/people).)","✗ The king ask three questions. → ✓ The king asks three questions. (One king → **asks**.)","✗ Salim want a well. → ✓ Salim wants a well. (One person → **wants**.)","✗ Theme with no evidence. → ✓ Theme + 'Salim says…' + 'The king says…' (Support the theme with **evidence**.)"],"arabic":"المغزى (theme) هو الدرس الكبير أو الرسالة التي تحملها القصة، وهو صحيح للجميع لا لشخصية واحدة فقط، ويُكتب جملة كاملة.\n\nاصعد سلّم المغزى: الأحداث ← تغيّر الشخصية أو ما أظهرته ← الدرس ← المغزى للجميع.\n\nالمغزى ليس كلمة واحدة (honesty) ولا تفصيلًا (كان في الكيس 90 قطعة).\n\nادعم المغزى بالأدلة: ما تقوله الشخصيات وتفعله، وكيف تنتهي القصة."},"video":{"script":[{"time":"00:00–00:20","narration":"Every story hides a big lesson. Let's climb the Theme Ladder!","on_screen":"Theme Ladder 🪜","visual":"A ladder with four steps glows."},{"time":"00:20–00:55","narration":"In The Merchant and the Honest Boy: events… change… lesson… THEME: Honesty is the best treasure!","on_screen":"events → change → lesson → theme","visual":"Story pictures climb the ladder step by step."},{"time":"00:55–02:05","narration":"The Clever Shepherd. Characters: Narrator, the King, Salim…","on_screen":"(play, acted)","visual":"Paper-puppet play in a palace: three riddles, laughter, a stick tapping the floor, the request for a well."},{"time":"02:05–02:40","narration":"Salim could ask for gold, but he asked for a well for everyone. What does that teach us?","on_screen":"Evidence 🔍","visual":"Salim's words and the king's words light up."},{"time":"02:40–03:00","narration":"Theme: The best use of a clever mind is to help other people!","on_screen":"Theme for everyone 🌍","visual":"Villagers drink from a new well; Salim smiles."}],"captions_ar":["كل قصة تخفي درسًا كبيرًا. لنصعد سلّم المغزى!","في «التاجر والفتى الأمين»: الأحداث… التغيّر… الدرس… المغزى: الأمانة أعظم كنز!","الراعي الذكي. الشخصيات: الراوي، والملك، وسالم…","كان يمكن لسالم أن يطلب ذهبًا، لكنه طلب بئرًا للجميع. ماذا يعلّمنا ذلك؟","المغزى: أفضل استخدام للعقل الذكي هو مساعدة الآخرين!"],"voice":"Narrator: American English, warm storyteller voice, speed 0.90. King: deep and amused. Salim: young, confident, polite."},"texts":[{"type":"reading","title":"The Clever Shepherd","body":"**Characters:** Narrator, the King, Salim (a young shepherd)\n\n**Scene:** The king's palace, long ago.\n\n**NARRATOR:** The king heard that a young shepherd in the mountains was very clever. He invited him to the palace.\n\n**KING:** *(smiling)* They say you are clever. Answer my three questions, and I will give you a reward. First, how many stars are in the sky?\n\n**SALIM:** As many as the hairs on my sheep, Your Majesty. Count them, and you will know!\n\n**KING:** *(laughing)* Second, where is the middle of the earth?\n\n**SALIM:** *(tapping the floor with his stick)* Right here! If you do not believe me, measure it.\n\n**KING:** Third, what do you want as your reward?\n\n**SALIM:** A new well for my village, so every family has water.\n\n**KING:** *(surprised)* You are clever AND kind. Your village will have its well!","word_count":138,"audio_id":"AUD-RW-L03-U5-LS3-T1","id":"TXT-RW-L03-U5-LS3-1","genre":"drama","role":"paired","difficulty":"350L–500L","glossary":[{"word":"Your Majesty","definition":"a polite way to speak to a king","arabic":"جلالتك"},{"word":"measure","definition":"find out how big or long something is","arabic":"يقيس"},{"word":"believe","definition":"think that something is true","arabic":"يصدّق"}]}],"activities":[{"id":"RW-L03-U5-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *The Clever Shepherd*. Choose the answer.","instructions_ar":"اقرأ المسرحية واختر الإجابة.","items":[{"q":"Why did the king invite Salim to the palace?","answer":"He heard that Salim was very clever.","explanation":"NARRATOR line.","explanation_ar":"سمع أنه ذكي جدًا.","options":["He heard that Salim was very clever.","Salim was his son.","Salim sold sheep.","Salim was lost."],"dok":1,"skill":"key details","text_id":"TXT-RW-L03-U5-LS3-1","stage":"controlled"},{"q":"How many questions did the king ask?","answer":"three","explanation":"Answer my three questions.","explanation_ar":"ثلاثة.","options":["three","one","two","ten"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How did Salim answer *How many stars are in the sky?*","answer":"As many as the hairs on his sheep.","explanation":"SALIM's first answer.","explanation_ar":"بعدد شعر غنمه.","options":["One hundred.","He did not know.","As many as the hairs on his sheep.","As many as the coins in the palace."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where did Salim say the middle of the earth is?","answer":"right where he tapped his stick","explanation":"SALIM: Right here!","explanation_ar":"حيث ضرب بعصاه.","options":["in the mountains","right where he tapped his stick","at the well","in the king's garden"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What did Salim ask for as his reward?","answer":"a new well for his village","explanation":"SALIM's last line.","explanation_ar":"بئر جديدة لقريته.","options":["a bag of gold","a palace","a hundred sheep","a new well for his village"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How did the king feel at the end?","answer":"surprised","explanation":"Stage direction: (surprised).","explanation_ar":"متفاجئ.","options":["angry","bored","sad","surprised"],"dok":1,"skill":"feelings","stage":"controlled"}]},{"id":"RW-L03-U5-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Theme. Choose.","instructions_ar":"المغزى: اختر.","items":[{"q":"Which statement about the play is a THEME, not a topic?","answer":"The best use of a clever mind is to help other people.","explanation":"A theme is a full lesson sentence.","explanation_ar":"جملة الدرس.","options":["cleverness","a shepherd","The best use of a clever mind is to help other people.","a well"],"dok":2,"skill":"theme vs. topic","stage":"guided"},{"q":"Which evidence BEST supports the theme of the play?","answer":"\"A new well for my village, so every family has water.\"","explanation":"It shows Salim helping others.","explanation_ar":"يُظهر مساعدته للآخرين.","options":["\"First, how many stars are in the sky?\"","\"A new well for my village, so every family has water.\"","\"Right here!\"","The king's palace, long ago."],"dok":2,"skill":"evidence","stage":"guided"},{"q":"What does Salim's choice of reward show about him?","answer":"He cares about other people.","explanation":"He asks for something for everyone.","explanation_ar":"يهتم بالآخرين.","options":["He cares about other people.","He is greedy.","He is afraid of the king.","He does not like water."],"dok":2,"skill":"character traits","stage":"guided"},{"q":"What is the theme of *The Merchant and the Honest Boy*?","answer":"Honesty is the best treasure.","explanation":"Stated at the end.","explanation_ar":"الأمانة أعظم كنز.","options":["Merchants are rich.","Wells are deep.","Honesty is the best treasure.","Gold is heavy."],"dok":1,"skill":"theme","stage":"guided"},{"q":"How are the themes of the two stories ALIKE?","answer":"Both show that good character is worth more than gold.","explanation":"Honesty and kindness over riches.","explanation_ar":"الخُلُق الطيب أثمن من الذهب.","options":["Both show that good character is worth more than gold.","Both say you should become a king.","Both say riddles are hard.","Both say sheep are important."],"dok":3,"skill":"compare themes","stage":"guided"},{"q":"Which is the WEAKEST theme statement?","answer":"kindness","explanation":"One word is not a theme.","explanation_ar":"كلمة واحدة.","options":["We should use our talents to help others.","Helping others is a great reward.","A kind heart is better than a full purse.","kindness"],"dok":2,"skill":"evaluate themes","stage":"guided"}]},{"id":"RW-L03-U5-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Theme Ladder for *The Clever Shepherd*.","instructions_ar":"أكمل سلّم المغزى للمسرحية.","items":[{"q":"Step 1 – Events.","answer":"The king asks three riddles. Salim answers cleverly and asks for a well for his village.","explanation":"Main events.","explanation_ar":"الأحداث الرئيسية.","dok":1,"skill":"events","stage":"freer"},{"q":"Step 2 – What does a character show or how does a character change?","answer":"Salim shows he is clever and kind; the king becomes surprised and admires him.","explanation":"Change / trait.","explanation_ar":"تغيّر / صفة.","dok":2,"skill":"character","stage":"freer"},{"q":"Step 3 – Lesson for the character.","answer":"Salim's kindness earns respect and helps his whole village.","explanation":"Lesson.","explanation_ar":"الدرس.","dok":2,"skill":"lesson","stage":"freer"},{"q":"Step 4 – Theme for everyone + one piece of evidence.","answer":"We should use our cleverness to help others. Evidence: Salim asks for a well so every family has water.","explanation":"Theme + evidence.","explanation_ar":"المغزى + دليل.","dok":3,"skill":"theme","stage":"freer"}]},{"id":"RW-L03-U5-LS3-A4","type":"open","stage":"production","instructions":"Writing: Think and write.","instructions_ar":"فكّر واكتب.","items":[{"q":"Why didn't Salim ask for gold?","answer":"He wanted to help his whole village, not only himself.","explanation":"Inference.","explanation_ar":"استنتاج.","dok":2,"skill":"inference","stage":"production"},{"q":"Which of Salim's answers was the cleverest? Why?","answer":"The stars answer, because nobody can count the hairs on his sheep or the stars.","explanation":"Opinion + reason.","explanation_ar":"رأي + سبب.","dok":3,"skill":"evaluate","stage":"production"},{"q":"Write the theme of the play in your own words.","answer":"A clever person is even better when he is kind.","explanation":"Your words.","explanation_ar":"بكلماتك.","dok":2,"skill":"theme","stage":"production"},{"q":"Give a real-life example of the theme.","answer":"A boy who is good at math helps his classmates with their homework.","explanation":"Real-life example.","explanation_ar":"مثال واقعي.","dok":3,"skill":"apply theme","stage":"production"}]},{"id":"RW-L03-U5-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Clever Shepherd\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Clever Shepherd”.","answer":"138 words","title":"The Clever Shepherd","body":"**Characters:** Narrator, the King, Salim (a young shepherd)\n\n**Scene:** The king's palace, long ago.\n\n**NARRATOR:** The king heard that a young shepherd in the mountains was very clever. He invited him to the palace.\n\n**KING:** *(smiling)* They say you are clever. Answer my three questions, and I will give you a reward. First, how many stars are in the sky?\n\n**SALIM:** As many as the hairs on my sheep, Your Majesty. Count them, and you will know!\n\n**KING:** *(laughing)* Second, where is the middle of the earth?\n\n**SALIM:** *(tapping the floor with his stick)* Right here! If you do not believe me, measure it.\n\n**KING:** Third, what do you want as your reward?\n\n**SALIM:** A new well for my village, so every family has water.\n\n**KING:** *(surprised)* You are clever AND kind. Your village will have its well!","words":138,"limit":133}],"time_limit_sec":133},{"id":"RW-L03-U5-LS3-ORG","type":"organizer","organizer":"Theme Ladder","instructions":"Organizer: Start at the bottom step and climb: events → character change → lesson → theme.","items":[{"q":"Step 1 – Events (what happened?)","answer":"The king asks three riddles; Salim answers cleverly; Salim asks for a well for his village."},{"q":"Step 2 – Character change (what did a character show or learn?)","answer":"Salim shows he is clever AND kind; the king is surprised and admires him."},{"q":"Step 3 – Lesson for the character","answer":"Salim's kindness earns the king's respect and a well for the village."},{"q":"Step 4 – Theme for everyone (+ evidence)","answer":"The best use of a clever mind is to help other people. Evidence: 'A new well for my village, so every family has water.' / 'You are clever AND kind.'"}]}],"game":{"name":"Climb the Theme Ladder","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Ladder climb: a short tale appears; the child answers one question per step (events, change, lesson, theme). Each correct answer moves a character up; a full climb rings a palace bell.","Teams get a folktale summary card.","They answer the four ladder steps in order on sticky notes.","At the top, they choose the best theme from three option cards and give evidence.","Other teams check the theme: is it a sentence for everyone?","Each correct step = 1 point; best theme with evidence = 3 points."],"data":[]},"exit_quiz":[{"q":"The theme of a story is ___.","answer":"the big lesson for everyone","explanation":"Theme = big lesson.","explanation_ar":"الدرس الكبير.","options":["the big lesson for everyone","the name of the main character","the first event","the place where it happens"],"dok":1,"skill":"theme"},{"q":"Which step comes FIRST on the Theme Ladder?","answer":"events","explanation":"Start with events.","explanation_ar":"الأحداث.","options":["theme","lesson","events","character change"],"dok":1,"skill":"organizer"},{"q":"*If you do not believe me, measure it.* *Measure* means ___.","answer":"find out how big or long something is","explanation":"Measure = find the size.","explanation_ar":"يقيس.","options":["throw away","find out how big or long something is","count coins","draw a picture"],"dok":1,"skill":"vocabulary"},{"q":"*Your Majesty* is a way to speak to ___.","answer":"a king or queen","explanation":"Polite title for a king.","explanation_ar":"الملك.","options":["a shepherd","a king or queen","a friend","a teacher"],"dok":1,"skill":"vocabulary"},{"q":"Which line shows that the king admired Salim?","answer":"\"You are clever AND kind.\"","explanation":"Praise shows admiration.","explanation_ar":"إعجاب الملك.","options":["\"First, how many stars are in the sky?\"","\"Second, where is the middle of the earth?\"","\"Third, what do you want as your reward?\"","\"You are clever AND kind.\""],"dok":2,"skill":"evidence"},{"q":"Which sentence about Salim is correct?","answer":"Salim asks for a well for his village.","explanation":"One person → asks.","explanation_ar":"صحيحة.","options":["Salim ask for a well for his village.","Salim asking for a well.","Salim asks a well for.","Salim asks for a well for his village."],"dok":2,"skill":"grammar"},{"q":"Why is *Salim gets a well* NOT a theme?","answer":"It is an event, not a lesson for everyone.","explanation":"Theme ≠ event.","explanation_ar":"لأنه حدث وليس درسًا.","options":["It is an event, not a lesson for everyone.","It is too long.","It is about the king.","It is a question."],"dok":2,"skill":"theme vs. event"},{"q":"Which theme fits BOTH the folktale and the play?","answer":"Good character is worth more than gold.","explanation":"Both value goodness over riches.","explanation_ar":"الخُلق الطيب أثمن من الذهب.","options":["Kings like riddles.","Wells are deep.","Merchants should count coins.","Good character is worth more than gold."],"dok":3,"skill":"compare themes"},{"q":"Why do writers put themes in stories?","answer":"to teach readers a lesson they can use in life","explanation":"Themes teach.","explanation_ar":"لتعليم القرّاء درسًا للحياة.","options":["to make stories shorter","to hide the characters","to teach readers a lesson they can use in life","to make readers sleepy"],"dok":3,"skill":"author's purpose"},{"q":"How does reading a play help you find the theme?","answer":"Characters' words and stage directions show their feelings and choices.","explanation":"Lines + directions = evidence.","explanation_ar":"الحوار والإرشادات تُظهر المشاعر والاختيارات.","options":["Plays have no themes.","Characters' words and stage directions show their feelings and choices.","Plays only have headings.","Plays never have kings."],"dok":2,"skill":"drama"}],"images":[{"id":"IMG-RW-L03-U5-LS3-V01","prompt":"Picture for the word 'riddle': a question mark with a smiling face"},{"id":"IMG-RW-L03-U5-LS3-V02","prompt":"Picture for the word 'Your Majesty': a boy bowing politely to a king"},{"id":"IMG-RW-L03-U5-LS3-V03","prompt":"Picture for the word 'measure': a child measuring with a tape"},{"id":"IMG-RW-L03-U5-LS3-V04","prompt":"Picture for the word 'believe': a person nodding with a check mark"},{"id":"IMG-RW-L03-U5-LS3-V05","prompt":"Picture for the word 'invite': a royal letter with a seal"},{"id":"IMG-RW-L03-U5-LS3-V06","prompt":"Picture for the word 'surprised': a face with raised eyebrows and an open mouth"},{"id":"IMG-RW-L03-U5-LS3-V07","prompt":"Picture for the word 'message': a scroll with a light bulb"},{"id":"IMG-RW-L03-U5-LS3-01","prompt":"Salim taps the palace floor with his stick while the king laughs."},{"id":"IMG-RW-L03-U5-LS3-02","prompt":"A ladder organizer for finding a theme."},{"id":"IMG-RW-L03-U5-LS3-03","prompt":"Villagers draw water from a new well."}],"audio":[{"id":"AUD-RW-L03-U5-LS3-V01","script":"riddle. The king asked three riddles."},{"id":"AUD-RW-L03-U5-LS3-V02","script":"Your Majesty. Yes, Your Majesty."},{"id":"AUD-RW-L03-U5-LS3-V03","script":"measure. Measure the table with a ruler."},{"id":"AUD-RW-L03-U5-LS3-V04","script":"believe. If you do not believe me, measure it."},{"id":"AUD-RW-L03-U5-LS3-V05","script":"invite. The king invited the shepherd to the palace."},{"id":"AUD-RW-L03-U5-LS3-V06","script":"surprised. The king was surprised by the answer."},{"id":"AUD-RW-L03-U5-LS3-V07","script":"message. The message of the play is to help others."},{"id":"AUD-RW-L03-U5-LS3-T1","script":"**Characters:** Narrator, the King, Salim (a young shepherd) **Scene:** The king's palace, long ago. **NARRATOR:** The king heard that a young shepherd in the mountains was very clever. He invited him to the palace. **KING:** *(smiling)* They say you are clever. Answer my three questions, and I will give you a reward. First, how many stars are in the sky? **SALIM:** As many as the hairs on my sheep, Your Majesty. Count them, and you will know! **KING:** *(laughing)* Second, where is the middle of the earth? **SALIM:** *(tapping the floor with his stick)* Right here! If you do not believe me, measure it. **KING:** Third, what do you want as your reward? **SALIM:** A new well for my village, so every family has water. **KING:** *(surprised)* You are clever AND kind. Your village will have its well!"},{"id":"AUD-RW-L03-U5-LS3-VID","script":"Every story hides a big lesson. Let's climb the Theme Ladder! In The Merchant and the Honest Boy: events… change… lesson… THEME: Honesty is the best treasure! The Clever Shepherd. Characters: Narrator, the King, Salim… Salim could ask for gold, but he asked for a well for everyone. What does that teach us? Theme: The best use of a clever mind is to help other people!"}]},{"id":"RW-L03-U5-LS4","title":"Writing Skill: Story beginning, middle and end","lesson_type":"writing_skill","objectives":["plan and write a story with a clear beginning, middle and end","make the problem grow in the middle and solve it at the end","use time words to move from one part to the next (One morning, By noon, At sunset)"],"objectives_ar":["التخطيط لقصة ذات بداية ووسط ونهاية واضحة وكتابتها.","جعل المشكلة تتصاعد في الوسط وحلّها في النهاية.","استخدام كلمات الوقت للانتقال بين الأجزاء."],"success_criteria":["I can write a beginning that tells who, where and what the character is like.","I can write a middle where the problem gets bigger.","I can write an end with a solution and a lesson."],"success_criteria_ar":["أستطيع كتابة بداية تخبر من وأين وكيف هي الشخصية.","أستطيع كتابة وسط تتصاعد فيه المشكلة.","أستطيع كتابة نهاية فيها حل ودرس."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"caravan","pos":"noun","ipa":"/ˈkærəvæn/","definition":"a group of people and animals traveling together, often across a desert","arabic":"قافلة","example":"The caravan crossed the desert.","image_id":"IMG-RW-L03-U5-LS4-V01","audio_id":"AUD-RW-L03-U5-LS4-V01","tier":"core"},{"word":"oasis","pos":"noun","ipa":"/oʊˈeɪsɪs/","definition":"a place in the desert with water and palm trees","arabic":"واحة","example":"They rested at the oasis.","image_id":"IMG-RW-L03-U5-LS4-V02","audio_id":"AUD-RW-L03-U5-LS4-V02","tier":"core"},{"word":"hurry","pos":"noun / verb","ipa":"/ˈhɝi/","definition":"to move or do things very fast; being in a rush","arabic":"عجلة / يستعجل","example":"Rami was always in a hurry.","image_id":"IMG-RW-L03-U5-LS4-V03","audio_id":"AUD-RW-L03-U5-LS4-V03","tier":"core"},{"word":"patient","pos":"adjective","ipa":"/ˈpeɪʃənt/","definition":"able to wait calmly","arabic":"صبور","example":"Be patient and wait your turn.","image_id":"IMG-RW-L03-U5-LS4-V04","audio_id":"AUD-RW-L03-U5-LS4-V04","tier":"core"},{"word":"water skin","pos":"noun","ipa":"/ˈwɔtər skɪn/","definition":"a bag made of leather for carrying water","arabic":"قِربة","example":"The leader carried a big water skin.","image_id":"IMG-RW-L03-U5-LS4-V05","audio_id":"AUD-RW-L03-U5-LS4-V05","tier":"core"},{"word":"beginning","pos":"noun","ipa":"/bɪˈɡɪnɪŋ/","definition":"the first part of a story","arabic":"البداية","example":"The beginning tells who and where.","image_id":"IMG-RW-L03-U5-LS4-V06","audio_id":"AUD-RW-L03-U5-LS4-V06","tier":"core"},{"word":"solution","pos":"noun","ipa":"/səˈluʃən/","definition":"the answer to a problem","arabic":"الحل","example":"The solution comes at the end.","image_id":"IMG-RW-L03-U5-LS4-V07","audio_id":"AUD-RW-L03-U5-LS4-V07","tier":"core"}],"explanation":{"text":"A good story has three parts. The **beginning** introduces the **character**, the **setting** (when and where) and what the character **wants** or is **like**.\n\nThe **middle** has the **problem**. Make it **grow**: one thing goes wrong, then another, then it is very serious. This keeps the reader excited.\n\nThe **end** has the **solution** – how the problem is solved – and shows how the character **changes**. A folktale often ends with a **lesson**. Use **time words** to move through the story: *Long ago… One day… By noon… At sunset… From that day on…*","examples":["Beginning: **Long ago, a young camel named Rami traveled with a caravan across the desert.**","Beginning (trait): **But Rami was always in a hurry.**","Middle (problem starts): **Rami drank only a little water and ran far ahead.**","Middle (problem grows): **By noon, the sun was burning, and Rami's mouth was dry.**","Middle (problem is serious): **Soon he was too tired to walk.**","End (solution): **The caravan leader gave him water from a big water skin.**","End (change): **From that day on, Rami always drank well and waited patiently.**","End (lesson): **It is wiser to be patient than to rush.**","Beginning openers: *Long ago… / Once upon a time… / In a small village…*"],"common_errors":["✗ Starting with the problem and no character. → ✓ Long ago, a young camel named Rami traveled with a caravan… (Introduce the **character and setting** first.)","✗ The problem is solved in one sentence in the middle. → ✓ Make the problem **grow** in the middle; solve it at the **end**. (Build the problem step by step.)","✗ Ending with 'And then he woke up. The end.' → ✓ From that day on, Rami always drank well and waited patiently. (Show the **change** and the **lesson**.)","✗ Rami run ahead. → ✓ Rami ran ahead. (Stories use the **past tense**: ran.)","✗ One morning the caravan stop. → ✓ One morning, the caravan stopped. (Comma after the time phrase; past tense.)","✗ Mixing two problems that are never solved. → ✓ Keep **one** main problem and solve it. (One clear problem.)"],"arabic":"للقصة الجيدة ثلاثة أجزاء: البداية تقدّم الشخصية والإطار (متى وأين) وما تريده الشخصية أو صفتها.\n\nالوسط فيه المشكلة، فاجعلها تتصاعد: شيء يسوء ثم آخر ثم تصبح خطيرة؛ هذا يشوّق القارئ.\n\nالنهاية فيها الحل، وتُظهر تغيّر الشخصية، وتنتهي الحكاية الشعبية غالبًا بدرس.\n\nاستخدم كلمات الوقت للتنقل: Long ago… One day… By noon… At sunset… From that day on…"},"video":{"script":[{"time":"00:00–00:20","narration":"Layla wrote a folktale about a camel who never waits. Let's see its three parts!","on_screen":"Beginning · Middle · End","visual":"A story path with three signposts in a desert."},{"time":"00:20–01:30","narration":"Long ago, a young camel named Rami traveled with a caravan across the desert…","on_screen":"(model story)","visual":"Animated caravan; Rami runs ahead; the sun burns; Rami lies tired; the caravan finds him at sunset."},{"time":"01:30–02:00","narration":"The beginning: who, where, what he is like. Rami is always in a hurry!","on_screen":"Beginning = character + setting","visual":"The first signpost lights up."},{"time":"02:00–02:30","narration":"The middle: the problem grows – a little water… running ahead… burning sun… too tired!","on_screen":"Middle = problem grows 📈","visual":"A problem meter rises with each event."},{"time":"02:30–03:00","narration":"The end: solution, change and lesson. It is wiser to be patient than to rush!","on_screen":"End = solution + change + lesson","visual":"Rami waits patiently in line at the oasis."}],"captions_ar":["كتبت ليلى حكاية عن جمل لا يصبر أبدًا. لنرَ أجزاءها الثلاثة!","في قديم الزمان سافر جمل صغير اسمه رامي مع قافلة عبر الصحراء…","البداية: من وأين وكيف هو. رامي دائمًا مستعجل!","الوسط: المشكلة تتصاعد: قليل من الماء… الجري بعيدًا… شمس حارقة… تعب شديد!","النهاية: الحل والتغيّر والدرس. الصبر أحكم من العجلة!"],"voice":"Narrator: American English, warm storyteller voice, speed 0.90. Layla reads her folktale; Rami the camel has a young, impatient voice."},"texts":[{"type":"model","title":"The Camel Who Would Not Wait (by Layla)","body":"Long ago, a young camel named Rami traveled with a caravan across the desert. The old camels always told him, \"Drink well at the oasis. The desert is long.\" But Rami was always in a hurry.\n\nOne morning, the caravan stopped at an oasis. Rami drank only a little water and ran far ahead. By noon, the sun was burning, and Rami's mouth was dry. He could not find any water, and soon he was too tired to walk.\n\nAt sunset, the caravan found Rami lying in the sand. The caravan leader gave him water from a big water skin, and the old camels walked slowly beside him. From that day on, Rami always drank well and waited patiently. He learned that it is wiser to be patient than to rush.","word_count":131,"audio_id":"AUD-RW-L03-U5-LS4-T1","id":"TXT-RW-L03-U5-LS4-1","genre":"model text","role":"model","difficulty":"350L–500L","glossary":[],"annotations":["**Beginning** (paragraph 1): introduces the **character** (Rami), the **setting** (long ago, the desert) and what the character is like (always in a hurry).","**Middle** (paragraph 2): the **problem** starts and gets **bigger** – he drinks a little, runs ahead, the sun burns, he is too tired to walk.","**End** (paragraph 3): the **solution** (the caravan finds him and helps), the **character changes** (he waits patiently) and the **lesson**.","**Time words** move the story: *One morning… By noon… At sunset… From that day on…*","**Dialogue** in the beginning gives a warning that comes true in the middle."]}],"activities":[{"id":"RW-L03-U5-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"What does the beginning of Layla's story tell?","answer":"who Rami is, where he is and what he is like","explanation":"Beginning = character + setting.","explanation_ar":"من وأين وكيف هو.","options":["who Rami is, where he is and what he is like","how the problem is solved","the lesson only","what happens at sunset"],"dok":1,"skill":"story parts","stage":"controlled"},{"q":"What is Rami's problem?","answer":"He drinks only a little and runs ahead, so he gets very thirsty and tired.","explanation":"Middle paragraph.","explanation_ar":"يشرب قليلًا ويركض فيتعب.","options":["He loses his caravan leader's map.","He is too slow.","He drinks only a little and runs ahead, so he gets very thirsty and tired.","He falls into a well."],"dok":1,"skill":"problem","stage":"controlled"},{"q":"How is Rami's problem solved?","answer":"The caravan finds him and gives him water.","explanation":"End paragraph.","explanation_ar":"تجده القافلة وتسقيه.","options":["He finds a river.","It starts to rain.","He flies home.","The caravan finds him and gives him water."],"dok":1,"skill":"solution","stage":"controlled"},{"q":"A place in the desert with water and palm trees is an ___.","answer":"oasis","explanation":"Oasis.","explanation_ar":"واحة.","options":["oasis","caravan","village","palace"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Someone who can wait calmly is ___.","answer":"patient","explanation":"Patient = waits calmly.","explanation_ar":"صبور.","options":["in a hurry","greedy","patient","foolish"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which time phrase shows the END of the story is near?","answer":"From that day on,","explanation":"It shows the change after the problem.","explanation_ar":"From that day on.","options":["Long ago,","From that day on,","One morning,","By noon,"],"dok":2,"skill":"time words","stage":"controlled"}]},{"id":"RW-L03-U5-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Beginning, middle or end? Choose.","instructions_ar":"بداية أم وسط أم نهاية؟ اختر.","items":[{"q":"*Long ago, a lazy fox lived near a farm.* Which part of a story is this?","answer":"beginning","explanation":"Character + setting.","explanation_ar":"البداية.","options":["beginning","middle","end","title"],"dok":1,"skill":"story parts","stage":"guided"},{"q":"*The fox fell into the well, and the water was getting deeper.* Which part is this?","answer":"middle","explanation":"The problem grows.","explanation_ar":"الوسط.","options":["beginning","end","lesson","middle"],"dok":1,"skill":"story parts","stage":"guided"},{"q":"*From that day on, the fox always looked before he jumped.* Which part is this?","answer":"end","explanation":"Change after the problem.","explanation_ar":"النهاية.","options":["beginning","middle","end","setting"],"dok":1,"skill":"story parts","stage":"guided"},{"q":"Which sentence makes the problem GROW in the middle?","answer":"Then the sun went down, and the fox got cold and scared.","explanation":"Things get worse.","explanation_ar":"تتصاعد المشكلة.","options":["The fox lived near a farm.","Then the sun went down, and the fox got cold and scared.","The fox learned his lesson.","Long ago, there was a fox."],"dok":2,"skill":"rising problem","stage":"guided"},{"q":"Which ending shows that the character CHANGED?","answer":"From then on, the fox thought carefully before he jumped.","explanation":"A change in behavior.","explanation_ar":"يُظهر التغيّر.","options":["The fox was red.","From then on, the fox thought carefully before he jumped.","The fox jumped into the well.","The farm had chickens."],"dok":2,"skill":"character change","stage":"guided"},{"q":"Which is the BEST beginning for a folktale?","answer":"Long ago, in a small village, there lived a greedy fox who wanted every chicken on the farm.","explanation":"Who, where and what he wants.","explanation_ar":"بداية كاملة.","options":["The fox jumped.","The end.","Then the fox was sad.","Long ago, in a small village, there lived a greedy fox who wanted every chicken on the farm."],"dok":2,"skill":"beginnings","stage":"guided"}]},{"id":"RW-L03-U5-LS4-A3","type":"sequence","stage":"freer","instructions":"Put in order: Put the story in order.","instructions_ar":"رتّب القصة.","items":[{"q":"Order the fox story.","answer":"Long ago, a greedy fox lived near a farm. → One night, he jumped into a well to drink. → The water was deep, and he could not climb out. → A kind goat helped him with a rope. → From that day on, the fox was kind to every goat.","explanation":"Beginning → middle → end.","explanation_ar":"بداية ← وسط ← نهاية.","stage":"freer","parts":["A kind goat helped him with a rope.","From that day on, the fox was kind to every goat.","Long ago, a greedy fox lived near a farm.","One night, he jumped into a well to drink.","The water was deep, and he could not climb out."],"target":["Long ago, a greedy fox lived near a farm.","One night, he jumped into a well to drink.","The water was deep, and he could not climb out.","A kind goat helped him with a rope.","From that day on, the fox was kind to every goat."]},{"q":"Build a middle sentence.","answer":"By noon, the sun was burning.","explanation":"Time phrase + event.","explanation_ar":"عبارة وقت + حدث.","stage":"freer","parts":["was burning.","the sun","By noon,"],"target":["By noon,","the sun","was burning."]},{"q":"Build an ending sentence.","answer":"From that day on, → Rami → waited patiently.","explanation":"End + change.","explanation_ar":"نهاية + تغيّر.","stage":"freer","parts":["From that day on,","waited patiently.","Rami"],"target":["From that day on,","Rami","waited patiently."]},{"q":"Build a beginning sentence.","answer":"Long ago, → a young camel → traveled with a caravan.","explanation":"Beginning + setting.","explanation_ar":"بداية + إطار.","stage":"freer","parts":["traveled with a caravan.","a young camel","Long ago,"],"target":["Long ago,","a young camel","traveled with a caravan."]}]},{"id":"RW-L03-U5-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write the parts of a story.","instructions_ar":"اكتب أجزاء القصة.","items":[{"q":"Write a beginning for a story about a proud lion.","answer":"Long ago, a proud lion lived in a forest. He thought he was better than all the other animals.","explanation":"Who + where + trait.","explanation_ar":"من + أين + صفة.","dok":2,"skill":"beginning","stage":"production"},{"q":"Write a middle where the lion's problem grows (two events).","answer":"One day, the lion got caught in a hunter's net. The more he pulled, the tighter the net became.","explanation":"Problem grows.","explanation_ar":"مشكلة تتصاعد.","dok":2,"skill":"middle","stage":"production"},{"q":"Write an end with a solution and a change.","answer":"A little mouse chewed the net and freed him. From that day on, the lion was kind to small animals.","explanation":"Solution + change.","explanation_ar":"حل + تغيّر.","dok":3,"skill":"end","stage":"production"},{"q":"Write the lesson of your lion story.","answer":"Even small friends can be a big help.","explanation":"Lesson.","explanation_ar":"الدرس.","dok":2,"skill":"lesson","stage":"production"}]}],"game":{"name":"Story Train","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Story train: cards roll in mixed; the child connects a beginning engine, two middle cars that make the problem grow, and an end caboose. A complete train toots and drives away.","Teams get a mixed pile of train cards from four stories.","They build four trains: engine → two cars → caboose.","Each middle must make the problem grow.","Teams read one train aloud with time words.","Each correct train = 3 points; best reading = bonus point."],"data":[]},"exit_quiz":[{"q":"Which part of a story introduces the character and the setting?","answer":"the beginning","explanation":"Beginning = who and where.","explanation_ar":"البداية.","options":["the beginning","the middle","the end","the lesson"],"dok":1,"skill":"story parts"},{"q":"Where does the problem usually GROW?","answer":"in the middle","explanation":"Middle = problem.","explanation_ar":"في الوسط.","options":["in the title","at the very end","before the beginning","in the middle"],"dok":1,"skill":"story parts"},{"q":"The *solution* is ___.","answer":"how the problem is solved","explanation":"Solution = answer to the problem.","explanation_ar":"الحل.","options":["the first sentence","the setting","how the problem is solved","a time word"],"dok":1,"skill":"vocabulary"},{"q":"*The caravan crossed the desert.* A *caravan* is ___.","answer":"a group traveling together across a desert","explanation":"Caravan.","explanation_ar":"قافلة.","options":["a kind of tent","a group traveling together across a desert","a palm tree","a big boat"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about Rami uses the past tense correctly?","answer":"Rami ran far ahead of the caravan.","explanation":"run → ran.","explanation_ar":"ran.","options":["Rami run far ahead.","Rami ran far ahead of the caravan.","Rami runned far ahead.","Rami running far ahead."],"dok":2,"skill":"grammar"},{"q":"Which time phrase about the caravan has the comma in the right place?","answer":"At sunset, the caravan found Rami.","explanation":"Comma after the time phrase.","explanation_ar":"الفاصلة بعد At sunset.","options":["At sunset the caravan, found Rami.","At, sunset the caravan found Rami.","At sunset, the caravan found Rami.","At sunset the caravan found, Rami."],"dok":2,"skill":"punctuation"},{"q":"Why should the problem grow in the middle?","answer":"to make the story exciting for the reader","explanation":"Rising action builds interest.","explanation_ar":"لجعل القصة مشوقة.","options":["to make the story shorter","to skip the end","to explain the title","to make the story exciting for the reader"],"dok":2,"skill":"author's craft"},{"q":"What is the lesson of *The Camel Who Would Not Wait*?","answer":"It is wiser to be patient than to rush.","explanation":"Last sentence.","explanation_ar":"الصبر أحكم من العجلة.","options":["Camels can fly.","The desert is cold.","Always run ahead.","It is wiser to be patient than to rush."],"dok":2,"skill":"lesson"},{"q":"A story ends with *Then he woke up. The end.* What is the best advice?","answer":"Show how the problem was solved and how the character changed.","explanation":"Endings need solution + change.","explanation_ar":"أظهر الحل والتغيّر.","options":["Add more characters at the end.","Show how the problem was solved and how the character changed.","Remove the beginning.","Write the story in the future tense."],"dok":3,"skill":"revising"},{"q":"Which pair shows a warning in the beginning that comes true in the middle?","answer":"'The desert is long – drink well.' → Rami gets very thirsty.","explanation":"Foreshadowing.","explanation_ar":"تحذير يتحقق.","options":["'The desert is long – drink well.' → Rami gets very thirsty.","'Rami is a camel.' → Rami walks.","'The sun is hot.' → It is cold at night.","'The caravan is big.' → It has camels."],"dok":3,"skill":"story structure"}],"images":[{"id":"IMG-RW-L03-U5-LS4-V01","prompt":"Picture for the word 'caravan': a line of camels and travelers on dunes"},{"id":"IMG-RW-L03-U5-LS4-V02","prompt":"Picture for the word 'oasis': palm trees around a small pool in the desert"},{"id":"IMG-RW-L03-U5-LS4-V03","prompt":"Picture for the word 'hurry': a camel running with speed lines"},{"id":"IMG-RW-L03-U5-LS4-V04","prompt":"Picture for the word 'patient': a camel waiting calmly in line"},{"id":"IMG-RW-L03-U5-LS4-V05","prompt":"Picture for the word 'water skin': a leather water skin"},{"id":"IMG-RW-L03-U5-LS4-V06","prompt":"Picture for the word 'beginning': a green flag at the start of a path"},{"id":"IMG-RW-L03-U5-LS4-V07","prompt":"Picture for the word 'solution': a key opening a lock"},{"id":"IMG-RW-L03-U5-LS4-01","prompt":"A young camel runs ahead of the caravan and is later given water at sunset."},{"id":"IMG-RW-L03-U5-LS4-02","prompt":"A path with signposts for beginning, middle and end."},{"id":"IMG-RW-L03-U5-LS4-03","prompt":"A meter showing a problem getting bigger."}],"audio":[{"id":"AUD-RW-L03-U5-LS4-V01","script":"caravan. The caravan crossed the desert."},{"id":"AUD-RW-L03-U5-LS4-V02","script":"oasis. They rested at the oasis."},{"id":"AUD-RW-L03-U5-LS4-V03","script":"hurry. Rami was always in a hurry."},{"id":"AUD-RW-L03-U5-LS4-V04","script":"patient. Be patient and wait your turn."},{"id":"AUD-RW-L03-U5-LS4-V05","script":"water skin. The leader carried a big water skin."},{"id":"AUD-RW-L03-U5-LS4-V06","script":"beginning. The beginning tells who and where."},{"id":"AUD-RW-L03-U5-LS4-V07","script":"solution. The solution comes at the end."},{"id":"AUD-RW-L03-U5-LS4-T1","script":"Long ago, a young camel named Rami traveled with a caravan across the desert. The old camels always told him, \"Drink well at the oasis. The desert is long.\" But Rami was always in a hurry. One morning, the caravan stopped at an oasis. Rami drank only a little water and ran far ahead. By noon, the sun was burning, and Rami's mouth was dry. He could not find any water, and soon he was too tired to walk. At sunset, the caravan found Rami lying in the sand. The caravan leader gave him water from a big water skin, and the old camels walked slowly beside him. From that day on, Rami always drank well and waited patiently. He learned that it is wiser to be patient than to rush."},{"id":"AUD-RW-L03-U5-LS4-VID","script":"Layla wrote a folktale about a camel who never waits. Let's see its three parts! Long ago, a young camel named Rami traveled with a caravan across the desert… The beginning: who, where, what he is like. Rami is always in a hurry! The middle: the problem grows – a little water… running ahead… burning sun… too tired! The end: solution, change and lesson. It is wiser to be patient than to rush!"}]},{"id":"RW-L03-U5-LS5","title":"Writing Workshop: A short folktale that teaches a lesson","lesson_type":"writing_workshop","objectives":["plan an original folktale with a Story Mountain: setting, problem, events, climax and resolution","write an 8-sentence folktale with a long-ago opening, a growing problem, a clear ending and a lesson","revise for a clear lesson, edit past-tense verbs and dialogue punctuation, and publish the folktale as a mini-book"],"objectives_ar":["التخطيط لحكاية شعبية أصيلة بجبل القصة: الإطار والمشكلة والأحداث والذروة والحل.","كتابة حكاية من 8 جمل ببداية قديمة ومشكلة متصاعدة ونهاية واضحة ودرس.","التحسين لوضوح الدرس، وتدقيق أفعال الماضي وترقيم الحوار، ونشر الحكاية في كتيّب صغير."],"success_criteria":["I can plan all parts of the Story Mountain.","I can write a folktale with a beginning, middle and end and a clear lesson.","I can punctuate one line of dialogue with quotation marks."],"success_criteria_ar":["أستطيع التخطيط لكل أجزاء جبل القصة.","أستطيع كتابة حكاية ببداية ووسط ونهاية ودرس واضح.","أستطيع ترقيم سطر حوار بعلامات التنصيص."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"peacock","pos":"noun","ipa":"/ˈpikɑk/","definition":"a large bird with long, colorful tail feathers","arabic":"طاووس","example":"The peacock opened its beautiful tail.","image_id":"IMG-RW-L03-U5-LS5-V01","audio_id":"AUD-RW-L03-U5-LS5-V01","tier":"core"},{"word":"sparrow","pos":"noun","ipa":"/ˈspæroʊ/","definition":"a small brown bird","arabic":"عصفور (دوري)","example":"A little sparrow sat on the branch.","image_id":"IMG-RW-L03-U5-LS5-V02","audio_id":"AUD-RW-L03-U5-LS5-V02","tier":"core"},{"word":"proud","pos":"adjective","ipa":"/praʊd/","definition":"thinking you are better than others (in a bad way); or happy about something good you did","arabic":"متكبّر / فخور","example":"The proud peacock laughed at the other birds.","image_id":"IMG-RW-L03-U5-LS5-V03","audio_id":"AUD-RW-L03-U5-LS5-V03","tier":"core"},{"word":"storm","pos":"noun","ipa":"/stɔrm/","definition":"very bad weather with strong wind and rain","arabic":"عاصفة","example":"A storm came over the hills.","image_id":"IMG-RW-L03-U5-LS5-V04","audio_id":"AUD-RW-L03-U5-LS5-V04","tier":"core"},{"word":"climax","pos":"noun","ipa":"/ˈklaɪmæks/","definition":"the most exciting moment of a story, at the top of the Story Mountain","arabic":"ذروة القصة","example":"The climax is when the storm traps the peacock.","image_id":"IMG-RW-L03-U5-LS5-V05","audio_id":"AUD-RW-L03-U5-LS5-V05","tier":"core"},{"word":"resolution","pos":"noun","ipa":"/ˌrɛzəˈluʃən/","definition":"how the problem is solved at the end of a story","arabic":"حل العقدة","example":"In the resolution, the sparrow helps the peacock.","image_id":"IMG-RW-L03-U5-LS5-V06","audio_id":"AUD-RW-L03-U5-LS5-V06","tier":"core"},{"word":"quotation marks","pos":"noun","ipa":"/kwoʊˈteɪʃən mɑrks/","definition":"the marks \" \" that go around the words someone says","arabic":"علامات التنصيص","example":"Put quotation marks around the words people say.","image_id":"IMG-RW-L03-U5-LS5-V07","audio_id":"AUD-RW-L03-U5-LS5-V07","tier":"core"}],"explanation":{"text":"Your folktale will be **8 sentences** long and teach **one lesson** (be kind, be honest, share, be patient, work hard, don't judge by looks).\n\nPlan with the **Story Mountain**: **setting** (Long ago, in…) → **problem** → **events** (the problem grows) → **climax** (the most exciting moment) → **resolution** (how it is solved) + **lesson**.\n\nUse the **past tense**, **time words** (One day, Suddenly, At last, From that day on) and **trait words** (proud, kind, greedy, wise). Add **one line of dialogue** with **quotation marks**: *\"Your feathers are plain,\" laughed the peacock.*","examples":["Setting: **Long ago, a proud peacock lived in a green valley.**","Problem: **Every day, he laughed at a little brown sparrow. \"Your feathers are so plain!\" he said.**","Event: **One afternoon, a big storm came over the hills.**","Climax: **The peacock's long, heavy tail got stuck in a thorn bush, and the water was rising.**","Resolution: **The little sparrow flew down and pulled the thorns away, one by one.**","Change: **The peacock was ashamed and thanked the sparrow.**","Ending: **From that day on, the peacock never laughed at the other birds.**","Lesson: **A kind heart is more beautiful than colorful feathers.**","Other lesson ideas: *Slow and steady wins the race. / Sharing makes friends. / Hard work brings rewards.*"],"common_errors":["✗ No lesson at the end. → ✓ Lesson: A kind heart is more beautiful than colorful feathers. (A folktale must **teach** something.)","✗ The peacock laugh at the sparrow. → ✓ The peacock laughed at the sparrow. (Use the **past tense**.)","✗ Your feathers are plain, said the peacock. → ✓ \"Your feathers are plain,\" said the peacock. (Put **quotation marks** around spoken words.)","✗ \"Thank you\" said the peacock. → ✓ \"Thank you,\" said the peacock. (Comma **inside** the quotation marks before said.)","✗ The problem is solved before the climax. → ✓ Climax first, then the resolution. (Follow the Story Mountain.)","✗ Too many characters (ten animals). → ✓ Two or three characters are enough. (Keep it short and clear.)"],"arabic":"حكايتك 8 جمل وتعلّم درسًا واحدًا (كن لطيفًا، كن أمينًا، شارك، اصبر، اجتهد، لا تحكم على المظهر).\n\nخطط بجبل القصة: الإطار (Long ago) ← المشكلة ← الأحداث المتصاعدة ← الذروة (أكثر لحظة إثارة) ← الحل ثم الدرس.\n\nاستخدم الماضي وكلمات الوقت وكلمات الصفات، وأضف سطر حوار واحدًا بين علامتي التنصيص مع فاصلة قبل إغلاقهما.\n\nيكفي شخصيتان أو ثلاث في حكاية قصيرة."},"video":{"script":[{"time":"00:00–00:20","narration":"Noura is writing her own folktale! It will teach a lesson in eight sentences.","on_screen":"Write a Folktale ✍️","visual":"Noura with a notebook under a palm tree; a paper peacock and sparrow beside her."},{"time":"00:20–00:55","narration":"Plan: setting, problem, events, climax at the top, resolution and lesson.","on_screen":"1 Plan – Story Mountain ⛰️","visual":"A mountain fills with sticky notes."},{"time":"00:55–01:55","narration":"Long ago, a proud peacock lived in a green valley. Every day, he laughed at a little brown sparrow…","on_screen":"2 Draft – 8 sentences","visual":"Paper-cut animation: the storm, the tail stuck in thorns, the sparrow pulling thorns away."},{"time":"01:55–02:20","narration":"Revise: Is the lesson clear? A kind heart is more beautiful than colorful feathers!","on_screen":"3 Revise – clear lesson 💡","visual":"The lesson line glows."},{"time":"02:20–02:40","narration":"Edit: past tense and quotation marks: \"Your feathers are so plain!\" he said.","on_screen":"4 Edit \" \" -ed","visual":"Quotation marks float into place."},{"time":"02:40–03:00","narration":"Publish: Noura's mini-book joins the class Folktale Library!","on_screen":"5 Publish 📚","visual":"A shelf of small handmade books labelled 'Our Folktales'."}],"captions_ar":["نورة تكتب حكايتها الشعبية الخاصة! ستعلّم درسًا في ثماني جمل.","التخطيط: الإطار، والمشكلة، والأحداث، والذروة في القمة، والحل والدرس.","في قديم الزمان عاش طاووس متكبّر في وادٍ أخضر، وكان كل يوم يسخر من عصفور بني صغير…","التحسين: هل الدرس واضح؟ القلب الطيب أجمل من الريش الملوّن!","التدقيق: زمن الماضي وعلامات التنصيص.","النشر: كتيّب نورة ينضم إلى مكتبة حكايات الفصل!"],"voice":"Narrator: American English, warm storyteller voice, speed 0.90. Noura reads her folktale; the peacock sounds proud, the sparrow small and kind."},"texts":[],"activities":[{"id":"RW-L03-U5-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is the best opening for a folktale?","answer":"Long ago, a proud peacock lived in a green valley.","explanation":"Long ago + who + where.","explanation_ar":"بداية مناسبة.","options":["The peacock is a bird.","Long ago, a proud peacock lived in a green valley.","Then the sparrow helped.","The lesson is kindness."],"dok":1,"skill":"openings","stage":"controlled"},{"q":"The most exciting moment of a story is the ___.","answer":"climax","explanation":"Climax = top of the mountain.","explanation_ar":"الذروة.","options":["climax","setting","title","lesson"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"How the problem is solved at the end is the ___.","answer":"resolution","explanation":"Resolution = solution.","explanation_ar":"حل العقدة.","options":["climax","setting","dialogue","resolution"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Very bad weather with strong wind and rain is a ___.","answer":"storm","explanation":"Storm.","explanation_ar":"عاصفة.","options":["storm","sparrow","valley","lesson"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which line from the peacock story is punctuated correctly?","answer":"\"Thank you,\" said the peacock.","explanation":"Quotation marks + comma inside.","explanation_ar":"صحيحة.","options":["\"Thank you\" said the peacock.","Thank you, said the peacock.","\"Thank you,\" said the peacock.","\"Thank you, said the peacock.\""],"dok":2,"skill":"dialogue punctuation","stage":"controlled"},{"q":"Which sentence tells the lesson of Noura's folktale?","answer":"A kind heart is more beautiful than colorful feathers.","explanation":"Lesson at the end.","explanation_ar":"الدرس.","options":["The peacock lived in a valley.","A storm came over the hills.","A kind heart is more beautiful than colorful feathers.","The sparrow was brown."],"dok":1,"skill":"lesson","stage":"controlled"}]},{"id":"RW-L03-U5-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the folktale in order.","instructions_ar":"رتّب الحكاية.","items":[{"q":"Order Noura's folktale.","answer":"Long ago, a proud peacock lived in a green valley. → Every day, he laughed at a little brown sparrow. → One afternoon, a big storm came. → The peacock's tail got stuck in a thorn bush. → The sparrow pulled the thorns away. → From that day on, the peacock was kind.","explanation":"Setting → problem → event → climax → resolution → change.","explanation_ar":"ترتيب جبل القصة.","stage":"guided","parts":["The peacock's tail got stuck in a thorn bush.","Every day, he laughed at a little brown sparrow.","The sparrow pulled the thorns away.","From that day on, the peacock was kind.","Long ago, a proud peacock lived in a green valley.","One afternoon, a big storm came."],"target":["Long ago, a proud peacock lived in a green valley.","Every day, he laughed at a little brown sparrow.","One afternoon, a big storm came.","The peacock's tail got stuck in a thorn bush.","The sparrow pulled the thorns away.","From that day on, the peacock was kind."]},{"q":"Build the peacock's line.","answer":"\"Your feathers → are so plain!\" → he said.","explanation":"Dialogue with quotation marks.","explanation_ar":"حوار بعلامات التنصيص.","stage":"guided","parts":["are so plain!\"","he said.","\"Your feathers"],"target":["\"Your feathers","are so plain!\"","he said."]},{"q":"Build a climax sentence.","answer":"Suddenly, → the water → began to rise.","explanation":"Climax sentence.","explanation_ar":"جملة الذروة.","stage":"guided","parts":["began to rise.","Suddenly,","the water"],"target":["Suddenly,","the water","began to rise."]},{"q":"Build a lesson sentence for a tortoise story.","answer":"The lesson is: → Slow and steady → wins the race.","explanation":"Lesson sentence.","explanation_ar":"جملة الدرس.","stage":"guided","parts":["wins the race.","The lesson is:","Slow and steady"],"target":["The lesson is:","Slow and steady","wins the race."]},{"q":"Build an opening about a donkey.","answer":"Long ago, → a lazy donkey → lived on a farm.","explanation":"Setting sentence.","explanation_ar":"جملة الإطار.","stage":"guided","parts":["Long ago,","lived on a farm.","a lazy donkey"],"target":["Long ago,","a lazy donkey","lived on a farm."]},{"q":"Build a resolution about an ant.","answer":"At last, → the ant → had enough food for winter.","explanation":"Resolution sentence.","explanation_ar":"جملة الحل.","stage":"guided","parts":["At last,","had enough food for winter.","the ant"],"target":["At last,","the ant","had enough food for winter."]}]},{"id":"RW-L03-U5-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your folktale on the Story Mountain.","instructions_ar":"خطط لحكايتك على جبل القصة.","items":[{"q":"Which lesson will your folktale teach? Who are your characters?","answer":"Sharing makes friends; a greedy squirrel and a hungry rabbit.","explanation":"Lesson + characters.","explanation_ar":"درس + شخصيات.","dok":1,"skill":"planning","stage":"freer"},{"q":"Setting and problem.","answer":"long ago, a snowy forest; the squirrel will not share his nuts","explanation":"Setting + problem.","explanation_ar":"إطار + مشكلة.","dok":2,"skill":"planning","stage":"freer"},{"q":"Events and climax.","answer":"a big wind blows the squirrel's nuts into the river; he is hungry and alone","explanation":"Events + climax.","explanation_ar":"أحداث + ذروة.","dok":2,"skill":"planning","stage":"freer"},{"q":"Resolution, change and lesson.","answer":"the rabbit shares carrots; the squirrel says sorry and shares next time; Sharing makes friends.","explanation":"Resolution + lesson.","explanation_ar":"حل + درس.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L03-U5-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and publish your folktale.","instructions_ar":"اكتب حكايتك وحسّنها ودققها وانشرها.","items":[{"q":"Write your setting, problem and one line of dialogue.","answer":"Long ago, a greedy squirrel lived in a snowy forest. He had a big pile of nuts, but he never shared. \"These nuts are all mine!\" he shouted.","explanation":"Setting + problem + dialogue.","explanation_ar":"إطار + مشكلة + حوار.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your events and the climax.","answer":"One night, a strong wind blew his nuts into the cold river. The squirrel was hungry and alone in the snow.","explanation":"Events + climax.","explanation_ar":"أحداث + ذروة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your resolution, the change and the lesson.","answer":"At last, a kind rabbit shared her carrots with him. From that day on, the squirrel always shared his nuts. The lesson is: Sharing makes friends.","explanation":"Resolution + lesson.","explanation_ar":"حل + درس.","dok":2,"skill":"writing","stage":"production"},{"q":"What did your partner suggest about your folktale? What did you change?","answer":"My partner said the problem did not grow, so I added the cold night and the snow.","explanation":"Revision note.","explanation_ar":"ملاحظة التحسين.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L03-U5-LS5-ORG","type":"organizer","organizer":"Story Mountain","instructions":"Organizer: Write notes from the bottom left (setting) up to the top (climax) and down to the resolution and lesson.","items":[{"q":"Setting – long ago, where, who","answer":"long ago; a green valley; a proud peacock and a little sparrow"},{"q":"Problem","answer":"the peacock laughs at the sparrow's plain feathers"},{"q":"Event (problem grows)","answer":"a big storm comes over the hills"},{"q":"Climax – the most exciting moment","answer":"the peacock's heavy tail is stuck in a thorn bush; water is rising"},{"q":"Resolution – how it is solved","answer":"the sparrow pulls the thorns away; the peacock thanks him and changes"},{"q":"Lesson","answer":"A kind heart is more beautiful than colorful feathers."}]},{"id":"RW-L03-U5-LS5-WR","type":"writing","instructions":"Writing: Write a short folktale (8 sentences) that teaches a lesson. Include a long-ago setting, a problem that grows, a climax, a resolution, one line of dialogue and the lesson. Write a short folktale (8 sentences) that teaches a lesson. Include a long-ago setting, a problem that grows, a climax, a resolution, one line of dialogue and the lesson.","instructions_ar":"اكتب حكاية شعبية قصيرة (8 جمل) تعلّم درسًا، فيها إطار قديم ومشكلة تتصاعد وذروة وحل وسطر حوار والدرس.","prompt":"Write a short folktale (8 sentences) that teaches a lesson. Include a long-ago setting, a problem that grows, a climax, a resolution, one line of dialogue and the lesson.","checklist":["My folktale starts long ago and tells who and where.","There is a clear problem that grows.","There is a climax and a resolution.","A character changes or learns something.","I wrote the lesson at the end.","I wrote one line of dialogue with quotation marks and a comma.","All verbs are in the past tense; I used at least two unit words."],"rubric_id":"RW-RUBRIC-5T","min_words":80,"max_words":160,"organizer":"Story Mountain (setting → problem → events → climax → resolution)","items":[{"q":"Write a short folktale (8 sentences) that teaches a lesson. Include a long-ago setting, a problem that grows, a climax, a resolution, one line of dialogue and the lesson.","answer":"Long ago, a proud peacock lived in a green valley. Every day, he laughed at a little brown sparrow. \"Your feathers are so plain!\" he said. One afternoon, a big storm came over the hills. The peacock's long, heavy tail got stuck in a thorn bush, and the water was rising fast. The little sparrow flew down and pulled the thorns away, one by one. The peacock was ashamed and thanked the sparrow, and from that day on, he never laughed at the other birds. The lesson is: A kind heart is more beautiful than colorful feathers.","_w":{"checklist":["My folktale starts long ago and tells who and where.","There is a clear problem that grows.","There is a climax and a resolution.","A character changes or learns something.","I wrote the lesson at the end.","I wrote one line of dialogue with quotation marks and a comma.","All verbs are in the past tense; I used at least two unit words."],"min":80,"max":160}}]}],"game":{"name":"Folktale Builder","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Story spinner: four wheels spin to choose a character, a setting, a problem and a lesson; the child orders five sentence starters on a Story Mountain to build a mini folktale and records it.","Each team draws one card from each deck.","Teams plan a five-part Story Mountain in 4 minutes.","Teams tell their folktale aloud, ending with the lesson.","Other teams name the climax and the lesson.","Clear Story Mountain + lesson = 3 points; best telling = bonus point."],"data":[]},"exit_quiz":[{"q":"How many sentences should your folktale have?","answer":"eight","explanation":"8 sentences.","explanation_ar":"ثماني.","options":["eight","two","twenty","one"],"dok":1,"skill":"task"},{"q":"In your folktale plan, what goes at the TOP of the Story Mountain?","answer":"the climax","explanation":"Top = climax.","explanation_ar":"الذروة.","options":["the setting","the lesson","the climax","the title"],"dok":1,"skill":"organizer"},{"q":"A small brown bird is a ___.","answer":"sparrow","explanation":"Sparrow.","explanation_ar":"عصفور.","options":["peacock","sparrow","camel","storm"],"dok":1,"skill":"vocabulary"},{"q":"*The proud peacock laughed at the other birds.* Here, *proud* means ___.","answer":"thinking he is better than others","explanation":"Proud (in a bad way).","explanation_ar":"متكبّر.","options":["very kind","very small","very hungry","thinking he is better than others"],"dok":1,"skill":"vocabulary in context"},{"q":"Which sentence about the peacock uses the past tense correctly?","answer":"The peacock laughed at the sparrow.","explanation":"laughed.","explanation_ar":"الماضي.","options":["The peacock laugh at the sparrow.","The peacock laughs at the sparrow yesterday.","The peacock laughed at the sparrow.","The peacock laughing at the sparrow."],"dok":2,"skill":"grammar"},{"q":"Which dialogue sentence from the squirrel story is punctuated correctly?","answer":"\"These nuts are mine!\" shouted the squirrel.","explanation":"Quotes around spoken words.","explanation_ar":"صحيحة.","options":["These nuts are mine! shouted the squirrel.","\"These nuts are mine! shouted the squirrel.\"","\"These nuts are mine\"! shouted the squirrel.","\"These nuts are mine!\" shouted the squirrel."],"dok":2,"skill":"dialogue punctuation"},{"q":"Which lesson fits a story about a lazy grasshopper who has no food in winter?","answer":"Hard work brings rewards.","explanation":"Lazy → no food.","explanation_ar":"الاجتهاد يجلب المكافأة.","options":["Be proud of your feathers.","Always run ahead.","Never go outside.","Hard work brings rewards."],"dok":2,"skill":"lesson"},{"q":"Why does a folktale need a character who changes?","answer":"It shows the lesson in action.","explanation":"Change = lesson learned.","explanation_ar":"يُظهر الدرس عمليًا.","options":["It makes the story shorter.","It shows the lesson in action.","It is needed for the title.","It replaces the problem."],"dok":3,"skill":"story structure"},{"q":"A partner's folktale has no climax – the problem is solved right away. What should they add?","answer":"an event where the problem becomes very serious before it is solved","explanation":"Build to a climax.","explanation_ar":"حدث تشتد فيه المشكلة.","options":["an event where the problem becomes very serious before it is solved","a second title","more characters with no jobs","a list of words"],"dok":3,"skill":"revising"},{"q":"Which folktale plan is the most complete?","answer":"setting, problem, events, climax, resolution, lesson and one line of dialogue","explanation":"All parts present.","explanation_ar":"الأكثر اكتمالًا.","options":["setting, problem, events, climax, resolution, lesson and one line of dialogue","a setting and a picture","a lesson only","three characters and no problem"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L03-U5-LS5-V01","prompt":"Picture for the word 'peacock': a peacock with its tail open"},{"id":"IMG-RW-L03-U5-LS5-V02","prompt":"Picture for the word 'sparrow': a small brown sparrow"},{"id":"IMG-RW-L03-U5-LS5-V03","prompt":"Picture for the word 'proud': a peacock with its nose in the air"},{"id":"IMG-RW-L03-U5-LS5-V04","prompt":"Picture for the word 'storm': dark clouds, wind and rain"},{"id":"IMG-RW-L03-U5-LS5-V05","prompt":"Picture for the word 'climax': a star at the top of a mountain"},{"id":"IMG-RW-L03-U5-LS5-V06","prompt":"Picture for the word 'resolution': a key opening a lock at the bottom of a mountain"},{"id":"IMG-RW-L03-U5-LS5-V07","prompt":"Picture for the word 'quotation marks': a speech bubble with big quotation marks"},{"id":"IMG-RW-L03-U5-LS5-01","prompt":"Noura's mini-book showing a sparrow helping a peacock."},{"id":"IMG-RW-L03-U5-LS5-02","prompt":"A Story Mountain organizer for a folktale."},{"id":"IMG-RW-L03-U5-LS5-03","prompt":"A speech bubble showing quotation marks."}],"audio":[{"id":"AUD-RW-L03-U5-LS5-V01","script":"peacock. The peacock opened its beautiful tail."},{"id":"AUD-RW-L03-U5-LS5-V02","script":"sparrow. A little sparrow sat on the branch."},{"id":"AUD-RW-L03-U5-LS5-V03","script":"proud. The proud peacock laughed at the other birds."},{"id":"AUD-RW-L03-U5-LS5-V04","script":"storm. A storm came over the hills."},{"id":"AUD-RW-L03-U5-LS5-V05","script":"climax. The climax is when the storm traps the peacock."},{"id":"AUD-RW-L03-U5-LS5-V06","script":"resolution. In the resolution, the sparrow helps the peacock."},{"id":"AUD-RW-L03-U5-LS5-V07","script":"quotation marks. Put quotation marks around the words people say."},{"id":"AUD-RW-L03-U5-LS5-VID","script":"Noura is writing her own folktale! It will teach a lesson in eight sentences. Plan: setting, problem, events, climax at the top, resolution and lesson. Long ago, a proud peacock lived in a green valley. Every day, he laughed at a little brown sparrow… Revise: Is the lesson clear? A kind heart is more beautiful than colorful feathers! Edit: past tense and quotation marks: \"Your feathers are so plain!\" he said. Publish: Noura's mini-book joins the class Folktale Library!"}]}],"unit_test":[{"q":"A person who buys and sells cloth and spices in the market is a ___.","answer":"merchant","explanation":"Merchant.","explanation_ar":"تاجر.","options":["merchant","shepherd","king","sparrow"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"The king and his family lived in a beautiful ___.","answer":"palace","explanation":"Palace.","explanation_ar":"قصر.","options":["well","oasis","palace","village"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Someone who wants more and more for himself is ___.","answer":"greedy","explanation":"Greedy.","explanation_ar":"طمّاع.","options":["greedy","honest","wise","brave"],"dok":1,"skill":"character traits","_part":"Part A – Vocabulary"},{"q":"*The girl was courageous; she was brave enough to climb the tall tree.* *Courageous* means ___.","answer":"brave","explanation":"Synonym clue: brave.","explanation_ar":"شجاعة.","options":["lazy","sleepy","greedy","brave"],"dok":1,"skill":"synonym clues","_part":"Part A – Vocabulary"},{"q":"*The old man was **wealthy**. He was very rich and had many camels.* *Wealthy* means ___.","answer":"rich","explanation":"Synonym clue: rich.","explanation_ar":"ثري.","options":["poor","young","kind","rich"],"dok":2,"skill":"synonym clues","_part":"Part A – Vocabulary"},{"q":"Which pair of folktale trait words are synonyms?","answer":"clever – smart","explanation":"Same meaning.","explanation_ar":"clever – smart.","options":["brave – afraid","clever – smart","honest – greedy","big – small"],"dok":1,"skill":"synonyms","_part":"Part A – Vocabulary"},{"q":"*The theme of the story is to be kind to others.* *Theme* means ___.","answer":"the big lesson","explanation":"Theme = big lesson.","explanation_ar":"المغزى.","options":["the first character","the big lesson","the setting","a riddle"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"*He did not do his homework. The consequence was a low grade.* *Consequence* means ___.","answer":"what happens because of an action","explanation":"Consequence = result.","explanation_ar":"العاقبة.","options":["a kind of homework","a teacher","what happens because of an action","a reward"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Vocabulary"},{"q":"Which sentence is the best BEGINNING for a folktale?","answer":"Long ago, a clever fox lived near a busy market.","explanation":"Long ago + who + where.","explanation_ar":"بداية مناسبة.","options":["Then the fox ran away.","The lesson is: be clever.","Long ago, a clever fox lived near a busy market.","Suddenly, it rained."],"dok":1,"skill":"story parts","_part":"Part D – Story skills"},{"q":"Which sentence makes the problem GROW?","answer":"Then the storm got stronger, and the bridge began to break.","explanation":"Things get worse.","explanation_ar":"تتصاعد المشكلة.","options":["Long ago, there was a bridge.","The lesson is: be careful.","From that day on, they were careful.","Then the storm got stronger, and the bridge began to break."],"dok":2,"skill":"rising problem","_part":"Part D – Story skills"},{"q":"Which line said by the sparrow is punctuated correctly?","answer":"\"I will help you,\" said the sparrow.","explanation":"Quotation marks + comma.","explanation_ar":"صحيحة.","options":["\"I will help you\" said the sparrow.","I will help you, said the sparrow.","\"I will help you,\" said the sparrow.","\"I will help you, said the sparrow.\""],"dok":2,"skill":"dialogue punctuation","_part":"Part D – Story skills"},{"q":"Which statement about an ant story is a THEME, not a topic?","answer":"Hard work brings rewards.","explanation":"A full lesson sentence.","explanation_ar":"جملة الدرس.","options":["Hard work brings rewards.","an ant","winter","food"],"dok":1,"skill":"theme","_part":"Part D – Story skills"},{"q":"Which ending shows a character's change?","answer":"From that day on, the lazy donkey worked hard every morning.","explanation":"A change in behavior.","explanation_ar":"يُظهر التغيّر.","options":["From that day on, the lazy donkey worked hard every morning.","The donkey was gray.","The donkey lived on a farm.","It was a sunny day."],"dok":2,"skill":"character change","_part":"Part D – Story skills"},{"q":"What is the past tense of *find*?","answer":"found","explanation":"Irregular past.","explanation_ar":"found.","options":["finded","found","finds","fund"],"dok":1,"skill":"past tense","_part":"Part D – Story skills"}],"unit_writing":{"task":"Write a short folktale (8 sentences) that teaches ONE of these lessons: 'Share what you have.' / 'Do not judge by looks.' / 'Hard work brings rewards.' Include a long-ago beginning, a problem that grows, a climax, an ending, one line of dialogue and the lesson.","model":"Long ago, a lazy grasshopper lived in a sunny field. All summer, he sang while the ants carried food to their home. \"Why do you work so hard?\" he laughed. When winter came, the field was covered in snow. The grasshopper was cold and very hungry, and he could not find a single seed. At last, he knocked on the ants' door, and they shared some of their food with him. From that day on, the grasshopper worked hard every summer. The lesson is: Hard work brings rewards.","marks":20}});
